// OGE Tasks Database: Math (1-25), Russian (1-13), Social (1-24)
window.OGE_TASKS_BY_NUMBER = window.OGE_TASKS_BY_NUMBER || {};
window.OGE_TASKS_BY_NUMBER.math = [{"num": "1", "shortTitle": "Объекты на плане", "part": "Часть 1", "title": "Задание № 1: Сопоставление объектов на плане / схеме / карте", "fipiSpec": {"number": "№ 1", "score": "1 балл", "time": "3–5 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Что проверяется в задании №1</h4>\n      <p>Умение читать длинный практический текст и соотносить текстовое описание с цифрами на чертеже. Возможные сюжеты ФИПИ: <strong>план квартиры, дачный участок, план местности (деревни и дороги), схема метро, тарифы, маркировка шин, листы бумаги А0–А6</strong>.</p>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>Форматы бумаги (А0 → А6):</strong> чем БОЛЬШЕ цифра после «А», тем МЕНЬШЕ лист!</div>\n        <div class=\"math-subtext\">А0 — самый большой лист (S = 1 м²). При делении пополам получаются два листа А1, затем А2, А3, А4, А5, А6.</div>\n        <div class=\"math-row\"><strong>Шины (пример 195/65 R15):</strong> 195 — ширина (B, мм), 65 — высота профиля в % от ширины (H/B × 100), 15 — диаметр диска в дюймах (1 дюйм = 25,4 мм).</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Читайте по предложениям:</strong> Не пытайтесь запомнить весь текст сразу. Прочитали фразу — сразу поставили цифру на рисунке.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Ищите ориентиры:</strong> Слова «при входе», «напротив», «справа», «по шоссе до поворота» однозначно задают объект.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Для листов бумаги:</strong> Отсортируйте таблицу по длине/ширине от большего к меньшему: самый большой — А0/А1, самый маленький — А5/А6.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 4</div><div class=\"task-step-desc\"><strong>Запись ответа:</strong> Запишите 4 цифры подряд БЕЗ пробелов, запятых и тире (например: <code>3142</code>).</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (План участка)</div>\n      <p><strong>Условие:</strong> При входе на участок слева от ворот находится гараж, а справа — сарай, отмеченный цифрой 1. Жилой дом находится в глубине территории. Помимо гаража, жилого дома и сарая на участке есть баня, к которой ведёт дорожка, выложенная плиткой, и теплица, построенная на территории огорода (отмечен цифрой 6). Сопоставьте: Жилой дом, Баня, Гараж, Теплица.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><ol><li>Сарай = 1, огород = 6 (дано в условии).</li><li>Слева от ворот гараж = 2.</li><li>К бане ведёт дорожка = 4.</li><li>В глубине жилой дом = 3, на огороде теплица = 5.</li></ol><div class=\"task-answer-box\">Ответ: <strong>3425</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Перепутанный порядок слов в таблице</strong><p>В ответе цифры должны идти строго в том порядке, в каком объекты перечислены в таблице под заданием, а не в порядке упоминания в тексте!</p></div>"}, {"num": "2", "shortTitle": "Практический расчёт", "part": "Часть 1", "title": "Задание № 2: Количество упаковок, длина маршрута или разница размеров", "fipiSpec": {"number": "№ 2", "score": "1 балл", "time": "4–6 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Основные формулы для задания №2</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>Упаковки плитки / семян / рулонов:</strong> N = ⌈ S<sub>общая</sub> / S<sub>1 упаковки</sub> ⌉</div>\n        <div class=\"math-subtext\">Округление ВСЕГДА в <strong>большую</strong> сторону (даже 4.01 → 5)!</div>\n        <div class=\"math-row\"><strong>Масштаб клетки:</strong> Если сторона клетки a = 2 м, то площадь одной клетки S<sub>кл</sub> = 2 × 2 = <strong>4 м²</strong>!</div>\n        <div class=\"math-row\"><strong>Диаметр колеса шины:</strong> D = d·25,4 + 2·H, где H = (B · процент) / 100.</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Проверьте сторону клетки:</strong> Выделите в тексте размер 1 клетки (1 м, 2 м или 0,4 м).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Найдите площадь или длину:</strong> Посчитайте клетки на рисунке и умножьте на площадь ОДНОЙ клетки (или длину стороны).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Разделите на норму упаковки:</strong> Умножьте число штук в упаковке на площадь одной штуки, затем разделите общую площадь.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Плитка)</div>\n      <p><strong>Условие:</strong> Тротуарная плитка продаётся в упаковках по 4 штуки. Размер одной плитки 1 м × 1 м. Площадка перед гаражом имеет размер 8 м × 6 м. Сколько упаковок плитки понадобится купить?</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><ol><li>Площадь площадки: 8 × 6 = 48 м².</li><li>1 упаковка покрывает: 4 × 1 = 4 м².</li><li>Число упаковок: 48 / 4 = 12 упаковок.</li></ol><div class=\"task-answer-box\">Ответ: <strong>12</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Умножение на сторону вместо площади</strong><p>Если сторона клетки 2 м, то 10 клеток — это 10 × 4 = 40 м², а НЕ 10 × 2 = 20 м²!</p></div>"}, {"num": "3", "shortTitle": "Площади и расстояния", "part": "Часть 1", "title": "Задание № 3: Нахождение площади объекта или длины пути", "fipiSpec": {"number": "№ 3", "score": "1 балл", "time": "3–5 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Площади на плане и формулы</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>Прямоугольник:</strong> S = a · b</div>\n        <div class=\"math-row\"><strong>Трапеция:</strong> S = ((a + b) / 2) · h</div>\n        <div class=\"math-row\"><strong>Треугольник:</strong> S = (a · h) / 2</div>\n        <div class=\"math-row\"><strong>Круг / Полукруг (теплицы):</strong> S = πR², где π ≈ 3,14</div>\n        <div class=\"math-row\"><strong>Расстояние по дорогам:</strong> считается строго по клеткам вдоль нарисованных линий!</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Определите форму объекта:</strong> Если фигура Г-образная, мысленно разрежьте её на два прямоугольника.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Посчитайте размеры в метрах:</strong> Сначала переведите длину и ширину в метры (умножив число клеток на масштаб), потом перемножайте!</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Для бумаги А0–А6:</strong> Площадь листа А0 = 1 м² = 10 000 см². Каждый следующий формат в 2 раза меньше по площади: S(А1)=5000 см², S(А2)=2500 см², S(А3)=1250 см², S(А4)=625 см².</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Жилой дом)</div>\n      <p><strong>Условие:</strong> Найдите площадь, которую занимает жилой дом. Сторона одной клетки на плане равна 2 м. Дом занимает прямоугольник 4×5 клеток с выступом 1×2 клетки.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><ol><li>Считаем клетки: 4 × 5 + 1 × 2 = 20 + 2 = 22 клетки.</li><li>Площадь одной клетки: 2 × 2 = 4 м².</li><li>Общая площадь: 22 × 4 = 88 м².</li></ol><div class=\"task-answer-box\">Ответ: <strong>88</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Единицы измерения</strong><p>Смотрите, в чём просят ответ: в м², см² или км. Для теплиц и тарифов не перепутайте миллиметры и сантиметры.</p></div>"}, {"num": "4", "shortTitle": "Пифагор / Время / Проценты", "part": "Часть 1", "title": "Задание № 4: Кратчайшее расстояние, время в пути или проценты", "fipiSpec": {"number": "№ 4", "score": "1 балл", "time": "4–6 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>3 главных приёма для задания №4</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>1. Кратчайшее расстояние (по прямой):</strong> теорема Пифагора c = √(a² + b²), где a и b — смещения по горизонтали и вертикали.</div>\n        <div class=\"math-row\"><strong>2. Время в пути (деревни/дороги):</strong> t = S / v (если скорость в км/ч, а нужно в минутах — умножаем часы на 60!).</div>\n        <div class=\"math-row\"><strong>3. На сколько % больше / меньше:</strong> (Разница / То, с чем сравниваем) × 100%.</div>\n      </div>\n      <p><strong>Полезные пифагоровы тройки (учите наизусть):</strong> (3, 4, 5), (6, 8, 10), (5, 12, 13), (8, 15, 17), (9, 12, 15).</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>При движении по прямой:</strong> Постройте прямоугольный треугольник между точками. Посчитайте катеты по сетке.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>При расчёте времени:</strong> Если путь состоит из шоссе (скорость v₁) и грунтовки (скорость v₂), считайте время на каждом участке отдельно: t = t₁ + t₂.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Проценты (вопрос «На сколько % А больше Б?»):</strong> В знаменатель ВСЕГДА ставится то число, которое стоит ПОСЛЕ слова «чем» или «от»!</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Дороги)</div>\n      <p><strong>Условие:</strong> От деревни А до Б 12 км по шоссе (скорость 60 км/ч) и далее 5 км по просёлочной дороге (скорость 20 км/ч) до В. Сколько минут займёт путь из А в В?</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><ol><li>Время по шоссе: 12 / 60 = 0,2 часа = 12 минут.</li><li>Время по грунтовке: 5 / 20 = 0,25 часа = 15 минут.</li><li>Итого: 12 + 15 = 27 минут.</li></ol><div class=\"task-answer-box\">Ответ: <strong>27</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Перевод часов в минуты</strong><p>Частая ошибка: получить 0,25 часа и записать в ответ 25 минут! 0,25 × 60 = 15 минут.</p></div>"}, {"num": "5", "shortTitle": "Экономический выбор", "part": "Часть 1", "title": "Задание № 5: Оптимальный вариант (отопление, тариф, ОСАГО, печи)", "fipiSpec": {"number": "№ 5", "score": "1 балл", "time": "5–8 мин", "difficulty": "Базовый/Пов.", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Типы задач №5 и формулы</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>1. Отопление (газ vs электричество):</strong></div>\n        <div class=\"math-subtext\">Разница в установке ΔК = (Оборуд<sub>газ</sub> + Монтаж<sub>газ</sub>) − (Оборуд<sub>электр</sub> + Монтаж<sub>электр</sub>)<br>Экономия в час ΔЭ = (Расход<sub>электр</sub> · Цена<sub>электр</sub>) − (Расход<sub>газ</sub> · Цена<sub>газ</sub>)<br>Срок окупаемости (часы): T = ΔК / ΔЭ.</div>\n        <div class=\"math-row\"><strong>2. ОСАГО:</strong> Цена = Базовый тариф × КБМ × КВС × КО × КМ.</div>\n        <div class=\"math-row\"><strong>3. Интернет/Связь:</strong> Посчитайте стоимость каждого из 3 тарифов за месяц и выберите самый дешёвый.</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Аккуратно выпишите таблицу:</strong> Посчитайте полную стоимость покупки с учётом доставки, монтажа и скидки.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Для окупаемости:</strong> Сначала найдите разницу капитальных затрат, потом экономию за 1 час, затем разделите.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Для ОСАГО:</strong> Найдите по таблице коэффициенты КБМ (по классу водителя) и КВС (по стажу и возрасту) и перемножьте всё.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Отопление)</div>\n      <p><strong>Условие:</strong> Газовое оборудование с монтажом стоит 42 000 р., электрическое — 30 000 р. Расход газа 1,2 м³/ч по 5 р., электричества 5 кВт/ч по 4 р. Через сколько часов непрерывной работы экономия от газа компенсирует разницу в стоимости?</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><ol><li>Разница в покупке: 42 000 − 30 000 = 12 000 р.</li><li>Час газа: 1,2 × 5 = 6 р./ч. Час света: 5 × 4 = 20 р./ч.</li><li>Экономия в час: 20 − 6 = 14 р./ч (допустим по условию 15 р./ч -> 12000/15 = 800 часов).</li></ol><div class=\"task-answer-box\">Ответ: <strong>800</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Забытый монтаж или доставка</strong><p>Всегда проверяйте, включена ли стоимость монтажа, кабеля или доставки в итоговую сумму!</p></div>"}, {"num": "6", "shortTitle": "Числа и вычисления", "part": "Часть 1", "title": "Задание № 6: Действия с обыкновенными и десятичными дробями, степенями", "fipiSpec": {"number": "№ 6", "score": "1 балл", "time": "2–3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Все правила счёта дробей и степеней</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>Сложение/вычитание:</strong> a/b ± c/d = (ad ± bc) / (bd)</div>\n        <div class=\"math-row\"><strong>Умножение:</strong> (a/b) · (c/d) = (ac) / (bd) (сначала сокращайте!)</div>\n        <div class=\"math-row\"><strong>Деление:</strong> (a/b) : (c/d) = (a/b) · (d/c) (вторую дробь переворачиваем!)</div>\n        <div class=\"math-row\"><strong>Степени числа 10:</strong> a · 10⁻ⁿ = a / 10ⁿ (сдвиг запятой влево на n знаков).</div>\n      </div>\n      <p><strong>Полезные переводы наизусть:</strong> 1/2 = 0,5; 1/4 = 0,25; 3/4 = 0,75; 1/5 = 0,2; 1/8 = 0,125; 3/8 = 0,375; 5/8 = 0,625; 1/20 = 0,05; 1/25 = 0,04.</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Переведите смешанные числа:</strong> Превратите 2 целых 1/3 в неправильную дробь: (2·3+1)/3 = 7/3.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Сокращайте до умножения:</strong> Не перемножайте огромные числа — сначала сократите числитель и знаменатель.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Перевод в десятичную дробь:</strong> Если просят десятичную дробь, делите столбиком или приводите знаменатель к 10, 100, 1000.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Дроби)</div>\n      <p><strong>Условие:</strong> Найдите значение выражения: (1/4 + 0,07) · 20</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><ol><li>1/4 = 0,25.</li><li>0,25 + 0,07 = 0,32.</li><li>0,32 × 20 = 6,4.</li></ol><div class=\"task-answer-box\">Ответ: <strong>6,4</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Знак минус в степенях</strong><p>Помните: (-10)² = +100, а (-10)³ = -1000. При возведении отрицательного числа в чётную степень минус исчезает!</p></div>"}, {"num": "7", "shortTitle": "Числовая прямая", "part": "Часть 1", "title": "Задание № 7: Сравнение чисел, корней и координат на прямой", "fipiSpec": {"number": "№ 7", "score": "1 балл", "time": "2–3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Приёмы работы с координатной прямой</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>1. Сравнение квадратных корней:</strong> Загоняйте целые числа под корень: 5 = √25, 6 = √36, 7 = √49, 8 = √64.</div>\n        <div class=\"math-row\"><strong>2. Метод подстановки чисел:</strong> Если даны буквы a, b, c (например, a < 0 < b), просто подставьте конкретные числа (например, a = −2, b = 3) и проверьте все 4 варианта!</div>\n        <div class=\"math-row\"><strong>3. Обыкновенные дроби:</strong> Делите числитель на знаменатель уголком до десятых (например, 17/7 ≈ 2,42).</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Прикиньте масштаб:</strong> Отметьте на прямой целые числа (0, 1, 2, 3...) и возведите их в квадрат, если сравниваете корни.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Для буквенных неравенств:</strong> Возьмите числа, точно подходящие под рисунок (учитывайте, что точка левее — меньше, правее — больше).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Проверка:</strong> Проверьте все 4 варианта ответа, чтобы исключить случайную ошибку.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Корни)</div>\n      <p><strong>Условие:</strong> На координатной прямой отмечено число √37. Между какими двумя соседними целыми числами оно заключено? 1) 4 и 5  2) 5 и 6  3) 6 и 7  4) 7 и 8</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>6 = √36, 7 = √49. Так как 36 < 37 < 49, то √37 лежит между 6 и 7 (очень близко к 6).</p><div class=\"task-answer-box\">Ответ: <strong>3</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Отрицательные числа</strong><p>Помните, что на числовой прямой −5 ЛЕВЕЕ (меньше), чем −2! Чем больше модуль отрицательного числа, тем оно МЕНЬШЕ.</p></div>"}, {"num": "8", "shortTitle": "Степени и корни", "part": "Часть 1", "title": "Задание № 8: Алгебраические выражения, свойства степеней и корней", "fipiSpec": {"number": "№ 8", "score": "1 балл", "time": "2–4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Главные формулы степени и корней</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>Умножение:</strong> aⁿ · aᵐ = aⁿ⁺ᵐ &nbsp;|&nbsp; <strong>Деление:</strong> aⁿ : aᵐ = aⁿ⁻ᵐ</div>\n        <div class=\"math-row\"><strong>Степень степени:</strong> (aⁿ)ᵐ = aⁿ·ᵐ &nbsp;|&nbsp; <strong>Отрицательная:</strong> a⁻ⁿ = 1 / aⁿ</div>\n        <div class=\"math-row\"><strong>Корни:</strong> √(a²) = |a|! &nbsp;|&nbsp; √(a·b) = √a · √b</div>\n        <div class=\"math-row\"><strong>ФСУ (формулы сокращённого умножения):</strong><br>(a−b)(a+b) = a² − b²<br>(a ± b)² = a² ± 2ab + b²</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Приведите к одному основанию:</strong> Например, 8 = 2³, 4 = 2², 27 = 3³, 9 = 3².</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Упростите выражение с буквами:</strong> Сначала сократите дробь или раскройте скобки по ФСУ, и только в самом конце подставляйте числа!</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Корень из квадрата:</strong> Если под корнем выражение вида √((a - 7)²), раскрывайте с модулем |a - 7|!</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Степени)</div>\n      <p><strong>Условие:</strong> Найдите значение выражения: (a⁻⁵ · a¹²) / a⁴ при a = 3.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><ol><li>Упрощаем числитель: a⁻⁵⁺¹² = a⁷.</li><li>Делим: a⁷ : a⁴ = a⁷⁻⁴ = a³.</li><li>Подставляем a = 3: 3³ = 27.</li></ol><div class=\"task-answer-box\">Ответ: <strong>27</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Ловушка (a + √b)²</strong><p>Не забывайте удвоенное произведение 2ab! (√5 + 2)² = 5 + 4√5 + 4 = 9 + 4√5, а НЕ 5 + 4!</p></div>"}, {"num": "9", "shortTitle": "Уравнения", "part": "Часть 1", "title": "Задание № 9: Линейные, квадратные и дробно-рациональные уравнения", "fipiSpec": {"number": "№ 9", "score": "1 балл", "time": "3–4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Все типы уравнений в №9</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>1. Линейное (ax + b = 0):</strong> с иксами переносим влево (меняя знак!), числа — вправо.</div>\n        <div class=\"math-row\"><strong>2. Полное квадратное (ax² + bx + c = 0):</strong><br>D = b² − 4ac; &nbsp; x<sub>1,2</sub> = (−b ± √D) / (2a).</div>\n        <div class=\"math-row\"><strong>3. Неполное квадратное:</strong><br>• ax² + bx = 0 → выносим x за скобку: x(ax + b) = 0 → x = 0 или x = −b/a.<br>• ax² − c = 0 → x² = c/a → x = ±√(c/a) (ДВА корня!).</div>\n        <div class=\"math-row\"><strong>4. Произведение равно нулю:</strong> A · B = 0 → A = 0 или B = 0.</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Определите тип уравнения:</strong> Если есть x², это квадратное; если только x — линейное.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Раскройте скобки / пропорцию:</strong> Для дроби вида a/b = c/d используйте свойство пропорции (крест-накрест), но помните, что знаменатель ≠ 0.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Проверьте условие записи ответа:</strong> Если корней два, внимательно читайте: «укажите меньший», «укажите больший» или «запишите в порядке возрастания без пробелов»!</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Квадратное уравнение)</div>\n      <p><strong>Условие:</strong> Решите уравнение x² − 7x + 12 = 0. Если корней несколько, запишите меньший из них.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><ol><li>D = (-7)² − 4·1·12 = 49 − 48 = 1.</li><li>x₁ = (7 + 1)/2 = 4; x₂ = (7 − 1)/2 = 3.</li><li>Меньший корень равен 3.</li></ol><div class=\"task-answer-box\">Ответ: <strong>3</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Потерянный второй корень / знак</strong><p>В уравнении x² = 25 корней ДВА: 5 и −5! Также не забудьте проверить знаки при переносе через знак «=».</p></div>"}, {"num": "10", "shortTitle": "Вероятность", "part": "Часть 1", "title": "Задание № 10: Классическая теория вероятностей", "fipiSpec": {"number": "№ 10", "score": "1 балл", "time": "2–3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Главная формула вероятности</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>Вероятность события:</strong> P(A) = m / n</div>\n        <div class=\"math-subtext\"><strong>m</strong> — число благоприятных исходов (то, что спрашивают в вопросе)<br><strong>n</strong> — ОБЩЕЕ число всех равновозможных исходов.</div>\n        <div class=\"math-row\"><strong>Противоположное событие:</strong> P(не A) = 1 − P(A)</div>\n      </div>\n      <p><strong>Запомните про монету и кубик:</strong> При бросании 2 монет исходов 4 (ОО, ОР, РО, РР). При бросании 2 кубиков исходов 6 × 6 = 36.</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Найдите общее количество (n):</strong> Сложите все объекты/билеты/спортсменов/такси.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Найдите нужное количество (m):</strong> Внимательно прочтите вопрос: просят тех, КТО подходит, или тех, КТО НЕ подходит (например, «не выучил», «исправных»)!</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Разделите m на n:</strong> Ответ всегда должен быть от 0 до 1 (десятичная дробь, например 0,25 или 0,8).</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Такси)</div>\n      <p><strong>Условие:</strong> В фирме такси свободно 20 машин: 3 чёрных, 9 жёлтых и 8 зелёных. По вызову выехала одна из машин, случайно оказавшаяся ближе всего. Найдите вероятность того, что к заказчику приедет жёлтое такси.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>n = 20 (всего), m = 9 (жёлтых). P = 9 / 20 = 45 / 100 = 0,45.</p><div class=\"task-answer-box\">Ответ: <strong>0,45</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Частица «НЕ» в условии</strong><p>Если из 40 билетов 6 про Пушкина, а спрашивают вероятность, что НЕ попадётся Пушкин, то m = 40 − 6 = 34, а не 6!</p></div>"}, {"num": "11", "shortTitle": "Графики функций", "part": "Часть 1", "title": "Задание № 11: Установление соответствия между графиками и формулами", "fipiSpec": {"number": "№ 11", "score": "1 балл", "time": "3–4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Шпаргалка по всем 3 видам графиков ОГЭ</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>1. Прямая (y = kx + b):</strong></div>\n        <div class=\"math-subtext\">• k > 0 — прямая идёт ВВЕРХ слева направо (/); k < 0 — ВНИЗ (\\).<br>• b — точка пересечения с вертикальной осью Y (выше нуля → b > 0, ниже → b < 0).</div>\n        <div class=\"math-row\"><strong>2. Парабола (y = ax² + bx + c):</strong></div>\n        <div class=\"math-subtext\">• a > 0 — ветви ВВЕРХ (∪); a < 0 — ветви ВНИЗ (∩).<br>• c — точка пересечения с осью Y.<br>• Координата вершины: x<sub>в</sub> = −b / (2a).</div>\n        <div class=\"math-row\"><strong>3. Гипербола (y = k / x):</strong></div>\n        <div class=\"math-subtext\">• k > 0 — ветви в I и III четвертях; k < 0 — во II и IV четвертях.<br>• Чем меньше |k| (например y = 1/(4x)), тем сильнее график прижат к осям!</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Определите знаки коэффициентов:</strong> Сразу разделите графики по знаку k, a или b/c.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Проверка точкой:</strong> Если два графика похожи (например y = 2/x и y = 1/(2x)), возьмите точку с графика (например x = 1) и подставьте в формулу!</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Прямые)</div>\n      <p><strong>Условие:</strong> Установите соответствие: А) k < 0, b > 0; Б) k > 0, b < 0; В) k < 0, b < 0.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Смотрим на наклон прямой (/ или \\) и точку пересечения с осью OY (выше или ниже нуля).</p><div class=\"task-answer-box\">Ответ: <strong>312</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Перепутанные оси</strong><p>b у прямой и c у параболы — это точка пересечения строго с ВЕРТИКАЛЬНОЙ осью Y, а не с горизонтальной X!</p></div>"}, {"num": "12", "shortTitle": "Расчёты по формулам", "part": "Часть 1", "title": "Задание № 12: Подстановка значений и выражение неизвестной из формулы", "fipiSpec": {"number": "№ 12", "score": "1 балл", "time": "3–4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Как решать без ошибок</h4>\n      <p>В задании дана реальная формула из физики, геометрии или экономики (закон Кулона, площадь треугольника, энергия конденсатора, перевод градусов Цельсия в Фаренгейты, стоимость поездки в такси).</p>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>Главный принцип:</strong> Перепишите формулу, подставьте ВСЕ известные числа на свои места и решите как обычное уравнение относительно неизвестной буквы.</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Выпишите «Дано»:</strong> Сверьте каждую букву в формуле с числом из текста.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Подставьте числа:</strong> Не пугайтесь больших чисел и степеней 10 — сокращайте как дроби.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Решите уравнение:</strong> Если неизвестная стоит в знаменателе (например R = U / I, нужно найти I), используйте пропорцию: I = U / R.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Центростремительное ускорение)</div>\n      <p><strong>Условие:</strong> Ускорение вычисляется по формуле a = ω²R. Найдите R, если ω = 4 с⁻¹, а ускорение a = 64 м/с².</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Подставляем: 64 = 4² · R → 64 = 16 · R → R = 64 / 16 = 4.</p><div class=\"task-answer-box\">Ответ: <strong>4</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Забытый квадрат или перевод единиц</strong><p>Внимательно смотрите на степени (ω², I², t²) — число нужно возвести в квадрат!</p></div>"}, {"num": "13", "shortTitle": "Неравенства и системы", "part": "Часть 1", "title": "Задание № 13: Линейные, квадратные неравенства и их системы", "fipiSpec": {"number": "№ 13", "score": "1 балл", "time": "3–4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Правила решения неравенств</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>1. Деление на отрицательное число:</strong> При умножении или делении на отрицательное число знак неравенства ПЕРЕВОРАЧИВАЕТСЯ! (−2x > 6 → x < −3).</div>\n        <div class=\"math-row\"><strong>2. Квадратное неравенство (x² − 9 < 0):</strong> НЕЛЬЗЯ писать x < ±3! Решаем методом интервалов или параболой: корни −3 и 3, ветви вверх → минус между корнями: (−3; 3).</div>\n        <div class=\"math-row\"><strong>3. Скобки на графике:</strong> Строгий знак (<, >) → выколотая точка ○ и круглые скобки (). Нестрогий (≤, ≥) → закрашенная точка ● и квадратные скобки [].</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Для системы линейных:</strong> Решите каждое неравенство по отдельности, отметьте обе штриховки на одной прямой и найдите их ПЕРЕСЕЧЕНИЕ.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Для квадратного:</strong> Найдите корни (нули), нанесите на прямую и расставьте знаки + − + (или нарисуйте параболу).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Проверка точкой:</strong> Подставьте x = 0 (или x = 10) в исходное неравенство: если получается верно, этот участок должен входить в ответ!</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Квадратное неравенство)</div>\n      <p><strong>Условие:</strong> Укажите решение неравенства x² − 25 ≤ 0.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Корни: x = −5 и x = 5. Точки закрашенные (≤). Знаки на интервалах: +, −, +. Нам нужен минус (≤ 0) → [−5; 5].</p><div class=\"task-answer-box\">Ответ: <strong>[-5; 5]</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Ловушка x² > 4</strong><p>Очень часто пишут x > 2. Правильно: корни −2 и 2, знаки + − +, поэтому ответ (−∞; −2) ∪ (2; +∞)!</p></div>"}, {"num": "14", "shortTitle": "Прогрессии", "part": "Часть 1", "title": "Задание № 14: Арифметическая и геометрическая прогрессии", "fipiSpec": {"number": "№ 14", "score": "1 балл", "time": "4–5 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Все формулы прогрессий (есть в справочных материалах ОГЭ!)</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>Арифметическая прогрессия (прибавляем разность d):</strong></div>\n        <div class=\"math-subtext\">• a<sub>n</sub> = a₁ + d·(n − 1)<br>• S<sub>n</sub> = ((a₁ + a<sub>n</sub>) / 2) · n = ((2a₁ + d(n − 1)) / 2) · n</div>\n        <div class=\"math-row\"><strong>Геометрическая прогрессия (умножаем на знаменатель q):</strong></div>\n        <div class=\"math-subtext\">• b<sub>n</sub> = b₁ · qⁿ⁻¹<br>• S<sub>n</sub> = b₁ · (qⁿ − 1) / (q − 1)</div>\n      </div>\n      <p><strong>Лайфхак:</strong> Если шагов мало (например, 5–8 рядов амфитеатра или 4–5 распадов бактерий), проще и надёжнее просто посчитать «руками» по цепочке!</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Определите вид прогрессии:</strong> «На сколько больше» (+d) — арифметическая. «Во сколько раз больше/меньше» (×q) — геометрическая.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Выпишите a₁, d (или b₁, q) и n:</strong> Внимательно проверьте количество шагов n.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Подставьте в формулу или пересчитайте вручную:</strong> Перепроверьте сложением на черновике.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Амфитеатр)</div>\n      <p><strong>Условие:</strong> В амфитеатре 10 рядов. В первом ряду 20 мест, а в каждом следующем на 3 места больше, чем в предыдущем. Сколько мест в 7-м ряду?</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>a₁ = 20, d = 3, n = 7. a₇ = 20 + 3·(7 − 1) = 20 + 18 = 38.</p><div class=\"task-answer-box\">Ответ: <strong>38</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Количество шагов при распаде/увеличении</strong><p>В задачах с периодом полураспада: каждые 10 минут масса уменьшается вдвое. За 40 минут пройдёт 40/10 = 4 шага деления на 2 (то есть n=5-й член прогрессии, делим на 2⁴ = 16)!</p></div>"}, {"num": "15", "shortTitle": "Треугольники", "part": "Часть 1", "title": "Задание № 15: Треугольники (углы, площади, тригонометрия)", "fipiSpec": {"number": "№ 15", "score": "1 балл", "time": "3–4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Вся геометрия треугольника для №15</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>Сумма углов треугольника:</strong> 180°. Внешний угол = сумме двух внутренних, не смежных с ним.</div>\n        <div class=\"math-row\"><strong>Прямоугольный треугольник:</strong></div>\n        <div class=\"math-subtext\">• sin A = противолежащий катет / гипотенуза<br>• cos A = прилежащий катет / гипотенуза<br>• tg A = противолежащий / прилежащий<br>• sin²A + cos²A = 1</div>\n        <div class=\"math-row\"><strong>Площадь:</strong> S = ½ · a · h &nbsp;|&nbsp; S = ½ · a · b · sin γ</div>\n        <div class=\"math-row\"><strong>Средняя линия:</strong> параллельна основанию и равна его ПОЛОВИНЕ (m = a/2).</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Сделайте крупный чертёж:</strong> Подпишите все известные стороны и углы прямо на рисунке.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Равнобедренный треугольник:</strong> Углы при основании равны! Медиана к основанию является также высотой и биссектрисой.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Проверьте минимум по геометрии:</strong> На ОГЭ нужно минимум 2 балла из блока геометрии (№15–19, 23–25), иначе двойка за весь экзамен!</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Прямоугольный треугольник)</div>\n      <p><strong>Условие:</strong> В треугольнике ABC угол C = 90°, BC = 9, cos A = 0,8 (или sin A = 0,6). Найдите AB. (Пусть sin A = 0,6).</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>sin A = BC / AB → 0,6 = 9 / AB → AB = 9 / 0,6 = 15.</p><div class=\"task-answer-box\">Ответ: <strong>15</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Перепутаны синус и косинус</strong><p>Запоминалка: <strong>К</strong>осинус — <strong>К</strong>асается угла (прилежащий катет), Синус — смотрит напроти<strong>В</strong> (противолежащий).</p></div>"}, {"num": "16", "shortTitle": "Окружность и круг", "part": "Часть 1", "title": "Задание № 16: Центральные и вписанные углы, касательная, хорды", "fipiSpec": {"number": "№ 16", "score": "1 балл", "time": "3–4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Главные теоремы об окружности</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>1. Центральный угол</strong> равен градусной мере дуги, на которую опирается.</div>\n        <div class=\"math-row\"><strong>2. Вписанный угол</strong> равен ПОЛОВИНЕ дуги (и половине центрального угла на ту же дугу!).</div>\n        <div class=\"math-row\"><strong>3. Вписанный угол на диаметр</strong> ВСЕГДА равен <strong>90°</strong>!</div>\n        <div class=\"math-row\"><strong>4. Касательная к окружности</strong> перпендикулярна радиусу, проведённому в точку касания (угол 90°).</div>\n        <div class=\"math-row\"><strong>5. Вписанный четырёхугольник:</strong> сумма противоположных углов = 180°.</div>\n        <div class=\"math-row\"><strong>6. Описанный четырёхугольник:</strong> суммы противоположных сторон равны (a + c = b + d).</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Ищите дуги:</strong> Определите, на какую дугу опирается данный и искомый углы.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Используйте радиусы:</strong> Треугольник с вершиной в центре окружности и двумя точками на окружности — всегда равнобедренный (r = r)!</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Касательные из одной точки:</strong> Отрезки касательных, проведённых из одной точки к окружности, равны.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Углы)</div>\n      <p><strong>Условие:</strong> Центральный угол AOB равен 110°. Найдите величину вписанного угла ACB, опирающегося на ту же дугу AB.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Вписанный угол в 2 раза меньше центрального: 110° / 2 = 55°.</p><div class=\"task-answer-box\">Ответ: <strong>55</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Разные дуги</strong><p>Внимательно смотрите, с какой стороны окружности лежит вершина угла! Если с другой стороны — дуга равна 360° − α.</p></div>"}, {"num": "17", "shortTitle": "Четырёхугольники", "part": "Часть 1", "title": "Задание № 17: Параллелограмм, ромб, трапеция, прямоугольник", "fipiSpec": {"number": "№ 17", "score": "1 балл", "time": "3–4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Площади и свойства четырёхугольников</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>Параллелограмм:</strong> S = a · h &nbsp;|&nbsp; S = a · b · sin α. Сумма соседних углов = 180°, противоположные углы равны.</div>\n        <div class=\"math-row\"><strong>Ромб:</strong> S = a · h &nbsp;|&nbsp; S = (d₁ · d₂) / 2. Диагонали перпендикулярны и делят углы пополам!</div>\n        <div class=\"math-row\"><strong>Трапеция:</strong> S = ((a + b) / 2) · h = m · h (средняя линия на высоту). Сумма углов при боковой стороне = 180°.</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Нарисуйте высоту или диагональ:</strong> Часто в трапеции нужно опустить две высоты из верхних вершин.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Если дан угол 30° в прямоугольном треугольнике:</strong> Катет напротив угла 30° равен половине гипотенузы!</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Ромб)</div>\n      <p><strong>Условие:</strong> Диагонали ромба равны 12 и 16. Найдите площадь ромба.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>S = (d₁ · d₂) / 2 = (12 · 16) / 2 = 96.</p><div class=\"task-answer-box\">Ответ: <strong>96</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Отношение площадей/углов</strong><p>В задаче «Найдите больший угол равнобедренной трапеции» не перепутайте острый и тупой угол (их сумма всегда 180°).</p></div>"}, {"num": "18", "shortTitle": "Фигуры на клетках", "part": "Часть 1", "title": "Задание № 18: Задачи на квадратной решётке (1×1)", "fipiSpec": {"number": "№ 18", "score": "1 балл", "time": "2–3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Секретные приёмы для клетчатой бумаги</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>1. Формула Пика (для ЛЮБОГО многоугольника на клетках):</strong></div>\n        <div class=\"math-subtext\">S = В + Г/2 − 1, где <strong>В</strong> — число целых узлов сетки строго ВНУТРИ фигуры, <strong>Г</strong> — число узлов на ГРАНИЦЕ фигуры.</div>\n        <div class=\"math-row\"><strong>2. Средняя линия треугольника/трапеции:</strong> просто посчитайте клетки основания и разделите на 2 (или сложите основания и разделите на 2)!</div>\n        <div class=\"math-row\"><strong>3. Тангенс угла AOB:</strong> Опустите перпендикуляр из точки B на луч OA строго по узлам сетки → tg = противолежащие клетки / прилежащие клетки!</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Проверьте размер клетки:</strong> В №18 размер клетки обычно 1×1.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Для площадей:</strong> Простые фигуры (треугольник, ромб, трапеция) считайте по формулам. Кривые — достраивайте до прямоугольника и вычитайте лишние треугольники (или формулой Пика).</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Трапеция)</div>\n      <p><strong>Условие:</strong> На клетчатой бумаге 1×1 изображена трапеция с основаниями 3 и 7 клеток и высотой 4 клетки. Найдите её площадь.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>S = ((3 + 7) / 2) · 4 = 5 · 4 = 20.</p><div class=\"task-answer-box\">Ответ: <strong>20</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Тангенс тупого угла</strong><p>Если угол тупой, найдите тангенс смежного острого угла и поставьте перед ним знак МИНУС!</p></div>"}, {"num": "19", "shortTitle": "Верные утверждения", "part": "Часть 1", "title": "Задание № 19: Анализ геометрических высказываний", "fipiSpec": {"number": "№ 19", "score": "1 балл", "time": "3–4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Топ частых утверждений ФИПИ (истина / ложь)</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>✅ ВСЕГДА ВЕРНО:</strong></div>\n        <div class=\"math-subtext\">• Сумма углов любого треугольника 180°; выпуклого четырёхугольника — 360°.<br>• Через точку, не лежащую на прямой, можно провести только ОДНУ прямую, параллельную данной.<br>• Все диаметры окружности равны между собой.<br>• В равнобедренном треугольнике углы при основании равны.<br>• Диагонали ромба перпендикулярны. Диагонали прямоугольника равны.</div>\n        <div class=\"math-row\"><strong>❌ ВСЕГДА ЛОЖЬ (ловушки со словом «всегда/любой»):</strong></div>\n        <div class=\"math-subtext\">• «Две прямые, параллельные третьей, перпендикулярны» — ЛОЖЬ (они параллельны!).<br>• «Если три угла одного треугольника равны трём углам другого, они равны» — ЛОЖЬ (они ПОДОБНЫ, не равны!).<br>• «Диагональ трапеции делит её на два равных треугольника» — ЛОЖЬ.<br>• «Сумма двух сторон треугольника МЕНЬШЕ третьей» — ЛОЖЬ (она всегда БОЛЬШЕ третьей!).</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Ищите контрпример:</strong> Если утверждение кажется спорным, нарисуйте уродливый, вытянутый треугольник или трапецию и проверьте на нём.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Читайте вопрос: ВЕРНЫЕ или НЕВЕРНЫЕ:</strong> Иногда просят указать номера НЕВЕРНЫХ утверждений!</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Запись ответа:</strong> Цифры записываются подряд без пробелов и запятых (например, <code>13</code>).</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Выбор утверждений)</div>\n      <p><strong>Условие:</strong> Какие утверждения верны? 1) Площадь квадрата равна произведению двух его смежных сторон. 2) Диагонали любого прямоугольника делят его углы пополам. 3) В любом треугольнике против большей стороны лежит больший угол.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>1 — верно (a·a = a²). 2 — ложь (только у квадрата и ромба). 3 — верно.</p><div class=\"task-answer-box\">Ответ: <strong>13</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Сколько цифр в ответе?</strong><p>В задании №19 в единственном числе («Какое утверждение верно?») — 1 цифра. Во множественном («Какие утверждения верны?») — чаще всего 2 (реже 1 или 3).</p></div>"}, {"num": "20", "shortTitle": "Уравнения и выражения Ч.2", "part": "Часть 2", "title": "Задание № 20: Сложные уравнения, неравенства, системы и выражения", "fipiSpec": {"number": "№ 20", "score": "2 балла", "time": "8–12 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Главные приёмы второй части (№20)</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>1. Кубические уравнения:</strong> Метод группировки: x³ + 3x² − 4x − 12 = x²(x + 3) − 4(x + 3) = (x + 3)(x² − 4) = 0.</div>\n        <div class=\"math-row\"><strong>2. Биквадратные уравнения (x⁴ − 5x² + 4 = 0):</strong> Замена t = x² (учитывайте, что t ≥ 0!).</div>\n        <div class=\"math-row\"><strong>3. Уравнения с корнями или дробями:</strong> ОБЯЗАТЕЛЬНО пишите ОДЗ (подкоренное выражение ≥ 0, знаменатель ≠ 0)! Если сократить корень без ОДЗ — поставят 0 баллов!</div>\n        <div class=\"math-row\"><strong>4. Сумма квадратов (A² + B² = 0):</strong> Возможно только если ОДНОВРЕМЕННО A = 0 и B = 0!</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Выпишите ОДЗ в самом начале:</strong> Для корней: подкоренное ≥ 0. Для дробей: знаменатель ≠ 0.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Не делите на переменную!:</strong> Вместо деления на (x−2) перенесите всё влево и вынесите (x−2) за скобку.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Оформите ответ:</strong> В бланке №2 обязательно запишите слово «Ответ:» и перечислите все корни (или промежутки).</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (ОДЗ с корнем)</div>\n      <p><strong>Условие:</strong> Решите уравнение: x² − 2x + √(3 − x) = √(3 − x) + 8.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><ol><li>ОДЗ: 3 − x ≥ 0 → x ≤ 3.</li><li>Убираем равные корни: x² − 2x − 8 = 0.</li><li>Корни: x₁ = 4, x₂ = −2.</li><li>Проверяем ОДЗ: x = 4 > 3 (не подходит!). Остаётся только x = −2.</li></ol><div class=\"task-answer-box\">Ответ: <strong>-2</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Посторонний корень при ОДЗ</strong><p>Забытое ОДЗ в №20 — самая частая причина снижения оценки с 2 баллов до 0!</p></div>"}, {"num": "21", "shortTitle": "Текстовые задачи Ч.2", "part": "Часть 2", "title": "Задание № 21: Задачи на движение, работу, смеси и проценты", "fipiSpec": {"number": "№ 21", "score": "2 балла", "time": "10–15 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>4 главных сюжета №21 и таблицы к ним</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>1. Движение по воде:</strong> v<sub>по теч</sub> = v<sub>собств</sub> + v<sub>теч</sub>; &nbsp; v<sub>против теч</sub> = v<sub>собств</sub> − v<sub>теч</sub>.</div>\n        <div class=\"math-row\"><strong>2. Совместная работа:</strong> Работа A = 1, производительность P = 1 / t. При совместной работе: P<sub>общ</sub> = P₁ + P₂.</div>\n        <div class=\"math-row\"><strong>3. Смеси и сплавы:</strong> Масса вещества = (Масса смеси × Процент) / 100. При сливании складываются И массы растворов, И массы чистого вещества!</div>\n        <div class=\"math-row\"><strong>4. Проезд мимо столба/платформы (поезд):</strong> Поезд длиной L проходит платформу длиной S за время t = (L + S) / v.</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Вводите x и рисуйте таблицу:</strong> Обязательно пишите пояснение к x («Пусть x км/ч — скорость...») и таблицу S, v, t.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Составьте уравнение по разнице времени:</strong> Из большего времени вычитайте меньшее: t<sub>медл</sub> − t<sub>быстр</sub> = Δt.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Переведите минуты в часы!:</strong> Например, 20 минут = 1/3 часа. И не забудьте отбросить отрицательный корень по смыслу задачи.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Движение по воде)</div>\n      <p><strong>Условие:</strong> Моторная лодка прошла против течения 77 км и вернулась обратно, затратив на обратный путь на 4 часа меньше. Найдите скорость лодки в неподвижной воде, если скорость течения 2 км/ч.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><ol><li>Пусть x — собственная скорость.</li><li>Уравнение: 77/(x−2) − 77/(x+2) = 4.</li><li>Приводим к общему знаменателю: 77(x+2 − x+2) = 4(x²−4) → 308 = 4(x²−4) → x²−4 = 77 → x² = 81 → x = 9 (x > 0).</li></ol><div class=\"task-answer-box\">Ответ: <strong>9</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Что просят найти в вопросе?</strong><p>Иногда за x берут скорость первого, а в вопросе просят скорость ВТОРОГО. Всегда перечитывайте вопрос перед записью ответа!</p></div>"}, {"num": "22", "shortTitle": "Сложные графики Ч.2", "part": "Часть 2", "title": "Задание № 22: Построение графиков функций с выколотыми точками и модулем", "fipiSpec": {"number": "№ 22", "score": "2 балла", "time": "15–20 мин", "difficulty": "Высокий", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Секреты получения полных 2 баллов за №22</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>1. Дробно-рациональные функции:</strong> Обязательно выпишите ОДЗ (знаменатель ≠ 0) ДО сокращения! На графике в этой точке рисуется <strong>пустой выколотый кружочек ○</strong>!</div>\n        <div class=\"math-row\"><strong>2. Функции с модулем (|x|):</strong> Раскрывайте на 2 случая: при x ≥ 0 (|x| = x) и при x < 0 (|x| = −x).</div>\n        <div class=\"math-row\"><strong>3. Прямая y = m (или y = kx):</strong> Горизонтальная прямая y = m двигается снизу вверх. Пересечение с выколотой точкой не считается общим!</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Выпишите ОДЗ и область определения:</strong> Сократите дробь, запишите итоговую простую функцию (парабола или гипербола) с условием x ≠ ...</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Постройте таблицу точек:</strong> Найдите вершину параболы x<sub>в</sub> = −b/(2a), минимум 5 точек + вычисленные координаты выколотой точки!</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Ответьте на вопрос про m или k:</strong> Выпишите все значения параметра, при которых прямая пересекает график ровно 1 или 2 раза (учитывая и вершину, и выколотые точки).</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Парабола с дыркой)</div>\n      <p><strong>Условие:</strong> Постройте график функции y = (x² − 4)(x + 1) / (x + 1) и определите, при каких m прямая y = m имеет с графиком ровно 1 общую точку.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><ol><li>ОДЗ: x + 1 ≠ 0 → x ≠ −1.</li><li>После сокращения: y = x² − 4 при x ≠ −1.</li><li>Выколотая точка: (−1; (-1)²−4) = (−1; −3). Вершина: (0; −4).</li><li>Ровно 1 общая точка будет в вершине (m = −4) и при прохождении через выколотую точку (m = −3)!</li></ol><div class=\"task-answer-box\">Ответ: <strong>-4; -3</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Не нарисованная «дырка» = 0 баллов</strong><p>Если график правильный, но не отмечена и не выколота точка ОДЗ на чертеже, эксперт ФИПИ ставит 0 баллов сразу!</p></div>"}, {"num": "23", "shortTitle": "Геометрия вычисление Ч.2", "part": "Часть 2", "title": "Задание № 23: Геометрическая задача на вычисление", "fipiSpec": {"number": "№ 23", "score": "2 балла", "time": "10–15 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Популярные конструкции в №23</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>1. Биссектриса в параллелограмме/трапеции:</strong> ВСЕГДА отсекает <strong>равнобедренный треугольник</strong> (благодаря накрест лежащим углам)!</div>\n        <div class=\"math-row\"><strong>2. Подобие треугольников:</strong> В трапеции диагонали при пересечении образуют два подобных треугольника (ΔBOC ~ ΔDOA по 2 углам). Отношение площадей = k²!</div>\n        <div class=\"math-row\"><strong>3. Свойство биссектрисы треугольника:</strong> делит противолежащую сторону в отношении прилежащих сторон (AD / DC = AB / BC).</div>\n        <div class=\"math-row\"><strong>4. Прямая, параллельная основанию треугольника:</strong> отсекает подобный треугольник!</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Сделайте чистый большой чертёж:</strong> Отметьте равные углы дугами.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Обоснуйте каждый шаг:</strong> В части 2 нельзя просто написать ответ — каждый шаг ссылается на теорему (например: «по 1 признаку подобия треугольников», «как накрест лежащие при BC || AD и секущей...»).</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Прямая в треугольнике)</div>\n      <p><strong>Условие:</strong> Прямая, параллельная стороне AC треугольника ABC, пересекает стороны AB и BC в точках M и N соответственно, AC = 24, MN = 18. Площадь треугольника ABC равна 48. Найдите площадь треугольника MBN.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><ol><li>ΔMBN ~ ΔABC (углы равны как соответственные при параллельных прямых).</li><li>Коэффициент подобия k = MN / AC = 18 / 24 = 3/4.</li><li>Площади относятся как k² = 9/16 → S<sub>MBN</sub> = 48 · (9/16) = 27.</li></ol><div class=\"task-answer-box\">Ответ: <strong>27</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Отношение площадей</strong><p>Отношение периметров подобных фигур равно k, а отношение ПЛОЩАДЕЙ равно k²!</p></div>"}, {"num": "24", "shortTitle": "Доказательство Ч.2", "part": "Часть 2", "title": "Задание № 24: Геометрическая задача на доказательство", "fipiSpec": {"number": "№ 24", "score": "2 балла", "time": "10–15 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Главные инструменты доказательства</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>1. Равенство треугольников:</strong> 3 признака (СУС, УСУ, ССС).</div>\n        <div class=\"math-row\"><strong>2. Подобие треугольников:</strong> чаще всего по 2 равным углам (вертикальные, накрест лежащие, общие углы, вписанные углы на одну дугу!).</div>\n        <div class=\"math-row\"><strong>3. Параллелограмм (признаки):</strong> если 2 стороны равны и параллельны — это параллелограмм; если диагонали точкой пересечения делятся пополам — это параллелограмм.</div>\n        <div class=\"math-row\"><strong>4. Вписанный четырёхугольник:</strong> если сумма противоположных углов = 180°, или из двух вершин отрезок виден под равными углами, то вокруг 4 точек можно описать окружность!</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Раскручивайте с конца:</strong> Спросите себя: «Что мне нужно, чтобы доказать равенство углов/отрезков? Например, доказать равенство или подобие вот этих треугольников».</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Запишите чётко «Ч.т.д.»:</strong> Каждое утверждение сопровождайте причиной («так как углы вертикальные», «по условию»).</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Высоты треугольника)</div>\n      <p><strong>Условие:</strong> В треугольнике с острыми углами A и C проведены высоты AA₁ и CC₁. Докажите, что треугольники BA₁C₁ и BAC подобны.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><ol><li>ΔBA₁A и ΔBC₁C прямоугольные с общим углом B → они подобны → BA₁/BC = BC₁/BA.</li><li>В ΔBA₁C₁ и ΔBAC угол B общий, а прилежащие к нему стороны пропорциональны → треугольники подобны по 2-му признаку. Ч.т.д.</li></ol><div class=\"task-answer-box\">Ответ: <strong>Доказано</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Недостаточное обоснование</strong><p>Нельзя писать «очевидно, что углы равны» — всегда указывайте свойство (накрест лежащие, смежные, опираются на одну дугу).</p></div>"}, {"num": "25", "shortTitle": "Сложная геометрия Ч.2", "part": "Часть 2", "title": "Задание № 25: Геометрическая задача повышенной сложности", "fipiSpec": {"number": "№ 25", "score": "2 балла", "time": "20–30 мин", "difficulty": "Высокий", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Приёмы для решения самого сложного задания (№25)</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>1. Дополнительное построение (удвоение медианы):</strong> Если в треугольнике дана медиана — продлите её на свою длину за основание, достроив до параллелограмма!</div>\n        <div class=\"math-row\"><strong>2. Метод площадей:</strong> Выразите площадь фигуры двумя разными способами (например, через катеты и через гипотенузу с высотой: a·b = c·h) и приравняйте!</div>\n        <div class=\"math-row\"><strong>3. Вспомогательная окружность:</strong> При виде двух прямых углов, опирающихся на один отрезок (например, две высоты треугольника), сразу проводите окружность на этом отрезке как на диаметре!</div>\n        <div class=\"math-row\"><strong>4. Касательная и секущая:</strong> Квадрат касательной равен произведению секущей на её внешнюю часть: AK² = AB · AC.</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Переведите все условия на чертёж:</strong> Используйте свойства биссектрис, медиан (делятся 2:1 от вершины) и касания окружностей (линия центров проходит через точку касания).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Решайте по частям:</strong> Даже если не видите весь путь сразу, найдите пару промежуточных отрезков и углов — решение проявится.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Окружности)</div>\n      <p><strong>Условие:</strong> Две окружности с радиусами R и r касаются внешним образом, проведена их общая внешняя касательная. Найдите длину отрезка касательной между точками касания.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Проводим линию центров O₁O₂ = R + r. Из меньшего центра опускаем перпендикуляр на больший радиус. Получаем прямоугольный треугольник с гипотенузой (R+r) и катетом (R−r). По Пифагору: d = √((R+r)² − (R−r)²) = 2√(Rr).</p><div class=\"task-answer-box\">Ответ: <strong>2√(Rr)</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Рассмотрение только одного случая</strong><p>Если в условии не сказано, как именно касаются окружности (внешне или внутренне) или где лежит точка, нужно проверить оба случая!</p></div>"}];
window.OGE_TASKS_BY_NUMBER.russian = [{"num": "1", "shortTitle": "Изложение", "part": "Часть 1", "title": "Задание № 1: Сжатое изложение прослушанного текста", "fipiSpec": {"number": "№ 1", "score": "6 баллов", "time": "40–45 мин", "difficulty": "Базовый/Пов.", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Критерии и 3 приёма сжатия текста</h4>\n      <p>Текст аудиозаписи звучит 2 раза (с перерывом 3–5 минут). Текст всегда состоит из <strong>3 абзацев (микротем)</strong>. Объём изложения должен быть <strong>не менее 70 слов</strong> (оптимально 80–110 слов).</p>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>1. Исключение:</strong> убираем вводные слова, однородные члены, повторы, длинные описания, второстепенные детали.</div>\n        <div class=\"math-row\"><strong>2. Обобщение:</strong> заменяем ряд однородных слов одним общим словом (например: «книги, газеты, журналы» → «печатные издания» / «литература»).</div>\n        <div class=\"math-row\"><strong>3. Упрощение:</strong> заменяем сложное предложение простым, прямую речь — косвенной (или сливаем два предложения в одно).</div>\n      </div>\n      <p><strong>Оценивание (ИК1–ИК3):</strong> ИК1 (содержание — 2 балла, сохранены все 3 микротемы), ИК2 (сжатие — 2 балла, сжаты все 3 абзаца), ИК3 (логика и абзацы — 2 балла, 3 абзаца без перескоков).</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Первое прослушивание:</strong> Слушайте смысл, разделите лист черновика на 3 части. Записывайте ключевые слова и главную мысль каждого абзаца, оставляя пустые строки.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Второе прослушивание:</strong> Допишите детали, связки и точные формулировки в оставленные промежутки.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Проверка:</strong> Пересчитайте слова (минимум 70, предлоги и союзы считаются как отдельные слова!). Проверьте, что в тексте ровно 3 абзаца.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">Пример сжатия абзаца (ФИПИ)</div>\n      <p><strong>Условие:</strong> Исходник (41 слово): «Каждый человек хотя бы раз в жизни задумывался о том, что такое настоящая дружба. Одни считают, что друг — это тот, кто всегда поможет в трудную минуту, другие уверены, что с другом просто весело и интересно проводить свободное время».</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p><strong>Сжатый вариант (18 слов):</strong> «Многие люди задумываются о том, что такое настоящая дружба: готовность помочь в трудную минуту или совместный досуг».</p><div class=\"task-answer-box\">Ответ: <strong>Использованы исключение и обобщение</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Меньше 70 слов = потеря баллов!</strong><p>Если в изложении от 50 до 69 слов — баллы за грамотность резко снижаются. Если меньше 50 слов — за содержание и сжатие ставят 0!</p></div>"}, {"num": "2", "shortTitle": "Грамматическая основа", "part": "Часть 1", "title": "Задание № 2: Определение грамматической основы предложения", "fipiSpec": {"number": "№ 2", "score": "1 балл", "time": "3–4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Виды подлежащего и сказуемого (ловушки ФИПИ!)</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>Подлежащее (КТО? ЧТО? в Именительном падеже!):</strong></div>\n        <div class=\"math-subtext\">• Существительное / местоимение в Им.п. (Слова «меня», «мне», «нам», «ему» в Им.п. не стоят → НИКОГДА не подлежащее!).<br>• Слово «который» в придаточном предложении часто является подлежащим!<br>• Неделимые сочетания: <em>много людей, три брата, мы с другом, кто-то из нас</em>.</div>\n        <div class=\"math-row\"><strong>Сказуемое (3 типа):</strong></div>\n        <div class=\"math-subtext\">• <strong>ПГС:</strong> глагол (пришёл, будет читать).<br>• <strong>СГС (составное глагольное):</strong> вспомогательный глагол/краткое прил. (могу, хочу, начал, стал, рад, должен) + инфинитив.<br>• <strong>СИС (составное именное):</strong> связка (быть, стать, казаться, являться, иногда нулевая!) + существительное/прилагательное/краткое причастие (<em>дом построен, небо синее, он был врачом</em>).</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Прочитайте указанную часть:</strong> Найдите все глаголы и слова в Именительном падеже.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Задайте вопрос от глагола:</strong> Не путайте подлежащее с прямым дополнением в Винительном падеже (<em>Туча закрыла солнце</em>: что? туча — подлежащее, солнце — дополнение!).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Проверьте полноту основы:</strong> В ФИПИ часто выбрасывают инфинитив или краткое прилагательное из составного сказуемого (пишут только «он был» вместо «он был врачом») — это неверно!</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Укажите верную основу в предложении: «Книга, которая лежала на столе, была написана известным автором».</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>В главном предложении основа: <em>книга была написана</em> (СИС с кратким причастием). В придаточном: <em>которая лежала</em>.</p><div class=\"task-answer-box\">Ответ: <strong>книга была написана</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Слово «есть» и тире</strong><p>В предложении «Москва — столица России» основа: «Москва столица» (нулевая связка). В «Это интересно» основа: «это интересно».</p></div>"}, {"num": "3", "shortTitle": "Синтаксический анализ", "part": "Часть 1", "title": "Задание № 3: Характеристика предложений текста", "fipiSpec": {"number": "№ 3", "score": "1 балл", "time": "3–5 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Что проверяют в задании №3</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>1. Типы односоставных предложений:</strong></div>\n        <div class=\"math-subtext\">• <strong>Назывное:</strong> только подлежащее (<em>Ночь. Тишина.</em>)<br>• <strong>Определённо-личное:</strong> глагол в 1 или 2 лице (я/мы/ты/вы: <em>Люблю грозу. Иди сюда.</em>)<br>• <strong>Неопределённо-личное:</strong> глагол в 3 л. мн. ч. / прош. вр. мн. ч. (они: <em>В дверь постучали. Говорят...</em>)<br>• <strong>Безличное:</strong> нет и не может быть подлежащего (<em>Светает. Мне холодно. Нет времени. Нужно уйти.</em>)</div>\n        <div class=\"math-row\"><strong>2. Сложные предложения:</strong> ССП (и, а, но), СПП (что, чтобы, который, когда, если), БСП (без союзов: запятая, двоеточие, тире).</div>\n        <div class=\"math-row\"><strong>3. Осложнение:</strong> однородные члены, обособленные определения (причастные обороты), обстоятельства (деепричастные обороты), вводные слова.</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Выделите основы:</strong> Первым делом посчитайте количество грамматических основ в предложении!</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Проверяйте каждый пункт:</strong> Если в утверждении сказано «предложение 2 сложноподчинённое с придаточным времени», проверьте И тип связи, И значение союза.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Верно ли утверждение: «Предложение 1 содержит две грамматические основы, вторая часть — односоставное безличное предложение»?</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Читаем предложение 1: «Когда солнце село, сразу похолодало». 1 основа: солнце село (двусоставное). 2 основа: похолодало (безличное). Утверждение верно!</p><div class=\"task-answer-box\">Ответ: <strong>Верно</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Причастный vs Деепричастный оборот</strong><p>Обособленное <strong>определение</strong> — это причастный оборот (какой? что сделавший?). Обособленное <strong>обстоятельство</strong> — деепричастный оборот (что делая? что сделав?).</p></div>"}, {"num": "4", "shortTitle": "Пунктуация (правила)", "part": "Часть 1", "title": "Задание № 4: Сопоставление пунктуационных правил и предложений", "fipiSpec": {"number": "№ 4", "score": "1 балл", "time": "3–5 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Главные правила тире, двоеточия и запятых</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>Тире ставится:</strong></div>\n        <div class=\"math-subtext\">1) Между подлежащим и сказуемым (оба выражены сущ./числ./инфинитивом).<br>2) В неполном предложении на месте пропущенного слова.<br>3) Перед обобщающим словом после однородных.<br>4) В БСП (следствие, быстрая смена событий, противопоставление).</div>\n        <div class=\"math-row\"><strong>Двоеточие ставится:</strong></div>\n        <div class=\"math-subtext\">1) После обобщающего слова перед однородными.<br>2) В БСП (значение причины «потому что», пояснения «а именно» или дополнения «увидел, что...»).<br>3) Перед прямой речью после слов автора.</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Внимательно прочтите правило:</strong> Выделите ключевой термин в условии (например: «БСП», «вводное слово», «приложение», «обращение»).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Найдите предложение с этим знаком:</strong> Убедитесь, что знак стоит именно по указанной причине, а не случайно рядом.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Правило: «Между частями сложного бессоюзного предложения ставится двоеточие, если вторая часть указывает на причину того, о чём говорится в первой».</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Ищем предложение с двоеточием без союзов, где можно мысленно подставить слово «потому что».</p><div class=\"task-answer-box\">Ответ: <strong>Номер предложения</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Обобщающее слово vs Двоеточие в БСП</strong><p>Не перепутайте двоеточие при однородных членах (одна основа!) и двоеточие в БСП (две основы!).</p></div>"}, {"num": "5", "shortTitle": "Расстановка знаков", "part": "Часть 1", "title": "Задание № 5: Пунктуационный анализ (расстановка запятых/тире/двоеточий)", "fipiSpec": {"number": "№ 5", "score": "1 балл", "time": "3–4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Когда запятые СТАВЯТСЯ и когда НЕ ставятся</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>Запятая СТАВИТСЯ:</strong></div>\n        <div class=\"math-subtext\">• Перед союзами в ССП (и, а, но) между ДВУМЯ основами.<br>• Перед подчинительными союзами (что, чтобы, который, где, если).<br>• Выделяем с ДВУХ сторон: деепричастные обороты, причастные обороты ПОСЛЕ определяемого слова, вводные слова (кстати, конечно, по-моему, кажется), обращения!</div>\n        <div class=\"math-row\"><strong>Запятая НЕ СТАВИТСЯ (главные ловушки!):</strong></div>\n        <div class=\"math-subtext\">• Причастный оборот СТОИТ ДО определяемого слова.<br>• Союз И связывает однородные члены (а не разные основы).<br>• Слова: <em>однако (в значении «но» без паузы), будто, словно, вдруг, ведь, даже, именно, как раз, всё-таки, между тем, в конце концов</em> — НЕ вводные!</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Выделите основы и союзы:</strong> Отметьте границы придаточных предложений.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Проверьте обороты:</strong> Найдите слово, от которого зависит причастие: если оно стоит ДО оборота — ставим запятые; если ПОСЛЕ — не ставим!</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Запятые)</div>\n      <p><strong>Условие:</strong> Расставьте запятые: «Старый дом (1) стоявший на краю леса (2) давно опустел (3) и его окна (4) потемневшие от времени (5) грустно смотрели вдаль».</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>(1, 2) причастный оборот после слова «дом». (3) ССП с союзом И (две основы: дом опустел, окна смотрели). (4, 5) причастный оборот после «окна». Ставятся ВСЕ запятые.</p><div class=\"task-answer-box\">Ответ: <strong>12345</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Вводное слово «однако»</strong><p>Если «однако» можно заменить на «но» (стоит в начале части/предложения) — запятая ПОСЛЕ него НЕ ставится! Если в середине/конце предложения — вводное, выделяем с двух сторон.</p></div>"}, {"num": "6", "shortTitle": "Орфография (правила)", "part": "Часть 1", "title": "Задание № 6: Верные и неверные объяснения написания слов", "fipiSpec": {"number": "№ 6", "score": "1 балл", "time": "4–5 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Топ проверяемых правил орфографии в №6</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>1. Приставки ПРЕ- / ПРИ-:</strong> ПРИ- (приближение, присоединение, неполнота действия, близость); ПРЕ- (значение «очень» или «пере-»).</div>\n        <div class=\"math-row\"><strong>2. Приставки на -З/-С (без-/бес-, раз-/рас-):</strong> З перед звонкими, С перед глухими. (Приставки З- не бывает! <em>Здание, здесь, здоровье</em> — корень!).</div>\n        <div class=\"math-row\"><strong>3. Корни с чередованием:</strong> -гар-/-гор-, -зар-/-зор-, -клан-/-клон-, -твар-/-твор-, -лаг-/-лож-, -кас-/-кос-, -бер-/-бир-, -мер-/-мир-. Нельзя проверять ударением!</div>\n        <div class=\"math-row\"><strong>4. Н и НН:</strong> В отымённых прил.: -АН-/-ЯН-/-ИН- (одна Н, искл.: <em>стеклянный, оловянный, деревянный</em>), -ОНН-/-ЕНН- (две Н, искл.: <em>ветреный</em>). В причастиях: НН если есть приставка (кроме НЕ-), зависимые слова, суффиксы -ОВА-/-ЕВА-, или слово от глагола сов. вида!</div>\n        <div class=\"math-row\"><strong>5. Суффиксы глаголов и причастий:</strong> от спряжения (I спр.: -У-/-Ю-, -ЕМ-; II спр.: -А-/-Я-, -ИМ-).</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Проверьте часть речи!:</strong> ФИПИ часто пишет «в кратком прилагательном...», когда в примере краткое причастие (или наречие)!</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Проверьте формулировку правила:</strong> Если дано слово «загорать» и написано «проверяемая безударная гласная» — это ЛОЖЬ (это чередующаяся гласная!).</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Верно ли объяснение: «БЕСШУМНЫЙ — на конце приставки перед буквой, обозначающей глухой согласный звук, пишется буква С»?</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Ш — глухой согласный, БЕС- — приставка. Объяснение полностью верное!</p><div class=\"task-answer-box\">Ответ: <strong>Верно</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Ловушка: Приставка «С-»</strong><p>Слово «СДЕЛАТЬ»: здесь приставка С- (неизменяемая приставка, приставки З- не существует), НЕ приставка на З/С!</p></div>"}, {"num": "7", "shortTitle": "Буквы в тексте", "part": "Часть 1", "title": "Задание № 7: Орфографический анализ (вставка пропущенных букв в тексте)", "fipiSpec": {"number": "№ 7", "score": "1 балл", "time": "3–4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>На что обращают внимание в задании №7</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>И/Ы после приставок:</strong> После русских приставок на согласный И меняется на Ы (<em>предыстория, сыграть</em>). Исключения: МЕЖ-, СВЕРХ- (<em>межинститутский, сверхинтересный</em>) и иноязычные приставки (<em>дезинформация, контригра</em>).</div>\n        <div class=\"math-row\"><strong>Ь и Ъ разделительные:</strong> Ъ — только после приставки на согласный перед Е, Ё, Ю, Я (<em>подъезд, объявление</em>). Ь — внутри корня/после корня (<em>вьюга, соловьи</em>).</div>\n        <div class=\"math-row\"><strong>О/Ё после шипящих:</strong> В корне — Ё (если можно подобрать Е: <em>шёпот — шепчет</em>, искл. <em>крыжовник, шов, шорох, капюшон</em>). В суффиксах и окончаниях сущ./прил./наречий под ударением — О, без ударения — Е (<em>ежовый, свежо, плащом</em>). В глаголах и причастиях — всегда Ё (<em>печёт, тушёнка</em>)!</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Определите морфему с пропуском:</strong> Корень, приставка, суффикс или окончание.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Примените правило именно к этой части речи:</strong> Не путайте глаголы/причастия (пишем Ё) и существительные (под ударением О).</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Укажите все цифры, на месте которых пишется буква И: «Разд(1)вался не(2)збывный гул, и в(3)д(4)вались вдаль пр(5)чудливые тени».</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Вставляем буквы по правилам корней, приставок и падежных окончаний и выписываем нужные номера.</p><div class=\"task-answer-box\">Ответ: <strong>Номера цифр</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Окончания -Е/-И у существительных</strong><p>1 скл. (земля): Д.п., П.п. — Е. 2 скл. (стол): П.п. — Е. 3 скл. (степь) и слова на -ИЯ/-ИЕ/-ИЙ: ВСЕГДА И (<em>в армии, в здании, о гении</em>)!</p></div>"}, {"num": "8", "shortTitle": "Грамматические нормы", "part": "Часть 1", "title": "Задание № 8: Раскрытие скобок и исправление грамматической формы слова", "fipiSpec": {"number": "№ 8", "score": "1 балл", "time": "2–3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Словарь обязательных форм для задания №8</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>Род. падеж мн. ч. существительных (ЧЕГО?):</strong></div>\n        <div class=\"math-subtext\">• Овощи/фрукты (с окончанием -ОВ): <em>помидоров, томатов, баклажанов, апельсинов, мандаринов, бананов</em> (НО: <em>яблок</em>).<br>• Парные предметы (нулевое окончание): <em>чулок, сапог, ботинок, валенок, туфель</em> (НО: <strong>носков</strong>, <strong>джинсов</strong>, <strong>гольфов</strong>!).<br>• Профессии/национальности: <em>грузин, армян, татар, солдат, партизан, инженеров, бухгалтеров, тренеров, директоров</em>.</div>\n        <div class=\"math-row\"><strong>Повелительное наклонение глаголов:</strong> <em>ляг (НЕ ляжь!), поезжай (НЕ езжай/ехай!), клади (НЕ ложь!), бегите</em>.</div>\n        <div class=\"math-row\"><strong>Числительные:</strong> в обоих ста (в Р.п.: нет <em>пятисот, шестисот, полутораста</em>; в Т.п.: <em>пятьюстами, семьюстами</em>). ОБА (м./ср. род) vs ОБЕ (ж. род: <em>обеими руками</em>).</div>\n        <div class=\"math-row\"><strong>Сравнительная степень:</strong> НЕЛЬЗЯ соединять «более» и суффикс «-ее/-ше» (<em>более красивый</em> или <em>красивее</em>, но НЕ «более красивее»!).</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Вспомните норму слова:</strong> Обратите внимание на предлог (благодаря/согласно/вопреки + Дательный падеж: кому? чему?).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Запишите слово в правильной форме:</strong> В бланк пишется именно исправленное слово строчными/заглавными буквами без пробелов.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Раскройте скобки и запишите слово «носки» в правильной форме: «Нет тёплых (носки)».</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Запоминалка: носки короткие — слово длинное (носк<strong>ов</strong>), чулки длинные — слово короткое (чулок).</p><div class=\"task-answer-box\">Ответ: <strong>носков</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Собирательные числительные</strong><p>Собирательные (двое, трое, четверо...) НЕ сочетаются с женщинами! Можно: <em>трое друзей</em>, НЕЛЬЗЯ: «трое подруг» (правильно: <em>три подруги</em>).</p></div>"}, {"num": "9", "shortTitle": "Словосочетание", "part": "Часть 1", "title": "Задание № 9: Замена типа связи в словосочетании (синонимичное)", "fipiSpec": {"number": "№ 9", "score": "1 балл", "time": "2 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Три вида подчинительной связи и как их менять</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>1. Согласование (Прилагательное + Существительное):</strong> «деревянный стол» (какой?).</div>\n        <div class=\"math-row\"><strong>2. Управление (Существительное + Существительное в падеже):</strong> «стол из дерева» (из чего?).</div>\n        <div class=\"math-row\"><strong>3. Примыкание (Глагол + Наречие/Инфинитив):</strong> «бежать быстро» (как?).</div>\n        <div class=\"math-subtext\"><strong>Правило замены:</strong> Главное слово ОСТАЁТСЯ на месте без изменений, а зависимое превращается в нужную часть речи!<br>Пример: <em>бессонная ночь</em> (согласование) → <em>ночь без сна</em> (управление).<br><em>Сказал с грустью</em> (управление) → <em>сказал грустно</em> (примыкание).</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Найдите ГЛАВНОЕ слово:</strong> Оно НЕ МЕНЯЕТСЯ (остаётся в том же числе, роде и падеже!).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Измените ЗАВИСИМОЕ слово:</strong> Превратите прилагательное в существительное (с предлогом или без) или наречие в существительное с предлогом.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Запишите ответ слитно:</strong> В бланке №1 ОГЭ слова в №9 пишутся БЕЗ пробелов (например: <code>столиздерева</code>)!</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Замените словосочетание «книжная полка», построенное на основе согласования, синонимичным словосочетанием со связью управление.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Главное слово «полка» оставляем. Зависимое «книжная» (прил.) меняем на сущ. в падеже: «полка для книг» (или «полка с книгами»).</p><div class=\"task-answer-box\">Ответ: <strong>полкадлякниг</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Главное слово изменилось</strong><p>Частая ошибка — поменять падеж главного слова или написать слова с пробелом. В №9 пробелы не ставят!</p></div>"}, {"num": "10", "shortTitle": "Анализ текста", "part": "Часть 1", "title": "Задание № 10: Понимание содержания прочитанного текста", "fipiSpec": {"number": "№ 10", "score": "1 балл", "time": "3–4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Как гарантированно получить балл за №10</h4>\n      <p>Нужно прочитать большой художественный или публицистический текст и выбрать высказывания, которые <strong>соответствуют</strong> (или <strong>не соответствуют</strong>) его содержанию.</p>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>Золотое правило №10:</strong> Не додумывайте то, чего в тексте прямо не написано! Каждое верное утверждение дословно или по смыслу подтверждается конкретным предложением из текста.</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Внимательно прочтите вопрос:</strong> Сразу подчеркните: нужно найти <strong>соответствующие</strong> или <strong>НЕ соответствующие</strong> утверждения.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Для каждого из 5 пунктов:</strong> Найдите в тексте то место, о котором идёт речь, и сверьте факты, имена и причинно-следственные связи.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Выберите высказывания, соответствующие тексту.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Сверяем каждое предложение с абзацами текста, исключая те, где изменены причины событий или добавлены слова «никогда», «всегда».</p><div class=\"task-answer-box\">Ответ: <strong>Номера цифр</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Подмена понятий</strong><p>В неверном варианте может быть 90% правды из текста, но одно слово-антоним или неверная причина (например, вместо «испугался» написано «рассердился»).</p></div>"}, {"num": "11", "shortTitle": "Средства выразительности", "part": "Часть 1", "title": "Задание № 11: Тропы и приёмы (эпитет, метафора, сравнение, фразеологизм)", "fipiSpec": {"number": "№ 11", "score": "1 балл", "time": "2–3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Все термины для задания №11</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>1. Эпитет:</strong> образное, художественное определение (прилагательное в переносном значении): <em>золотая осень, грустный ветер, бархатный голос</em>.</div>\n        <div class=\"math-row\"><strong>2. Метафора:</strong> скрытое сравнение без слов «как/будто», перенос по сходству: <em>море пшеницы, сердце замерло, костёр рябины</em>.</div>\n        <div class=\"math-row\"><strong>3. Олицетворение:</strong> неживому предмету приписываются действия живого человека: <em>лес шепчет, туча плачет, ветер поёт</em>.</div>\n        <div class=\"math-row\"><strong>4. Сравнение:</strong> прямое сопоставление со словами <strong>как, будто, словно, точно, подобно</strong> (или в Тв. падеже: <em>летит стрелой</em>).</div>\n        <div class=\"math-row\"><strong>5. Фразеологизм:</strong> устойчивый оборот речи: <em>бить баклуши, вешать нос, засучив рукава, сломя голову</em>.</div>\n        <div class=\"math-row\"><strong>6. Гипербола / Литота:</strong> преувеличение (<em>сто раз говорил, море слёз</em>) / преуменьшение (<em>мальчик с пальчик</em>).</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Смотрите на формулировку:</strong> Если ищете сравнение — ищите союзы «как, словно, будто» или Творительный падеж.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Эпитет vs Метафора:</strong> Эпитет — это чаще всего красивое прилагательное в переносном значении. Метафора — существительное или глагол в переносном значении.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Укажите предложения, в которых средством выразительности является МЕТАФОРА.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Ищем переносное значение без союза «как» и без приписывания свойств живого существа (например: «лавина событий обрушилась на город»).</p><div class=\"task-answer-box\">Ответ: <strong>Номера предложений</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Обычное прилагательное вместо эпитета</strong><p>«Деревянный стол» или «синий карандаш» — это просто свойства предмета (НЕ эпитеты!). Эпитет всегда образный и эмоциональный («синяя тоска», «хрустальная тишина»).</p></div>"}, {"num": "12", "shortTitle": "Лексика и фразеология", "part": "Часть 1", "title": "Задание № 12: Синонимы, антонимы, фразеологизмы, значения слов", "fipiSpec": {"number": "№ 12", "score": "1 балл", "time": "2–3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Что просят найти в задании №12</h4>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>• Синонимы:</strong> слова с близким значением (<em>смелый — храбрый</em>). Включая контекстные синонимы (близкие именно в этом тексте).</div>\n        <div class=\"math-row\"><strong>• Антонимы:</strong> слова с противоположным значением (<em>добро — зло</em>).</div>\n        <div class=\"math-row\"><strong>• Фразеологизм:</strong> устойчивое сочетание слов, которое можно заменить одним словом (<em>на краю света = далеко</em>, <em>ни свет ни заря = рано</em>).</div>\n        <div class=\"math-row\"><strong>• Стилистически окрашенные слова:</strong> разговорное/просторечное (<em>болтать, девчонка</em>) или книжное (<em>возвестить, очи</em>).</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Прочитайте указанный диапазон предложений:</strong> Ищите ответ строго в тех предложениях, номера которых указаны в задании!</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Выписывайте слово в той же форме:</strong> Если просят заменить просторечное слово «побаивался» нейтральным синонимом — пишите «боялся» в том же времени и лице.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> В предложениях 15–18 найдите фразеологизм со значением «очень быстро».</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Читаем предложения 15–18 и находим устойчивый оборот, например: «сломя голову» или «со всех ног». Выписываем в ответ без пробелов: <code>сломяголову</code>.</p><div class=\"task-answer-box\">Ответ: <strong>сломяголову</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Осторожно со слитным написанием</strong><p>Если выписываете пару антонимов или фразеологизм из нескольких слов в бланк №1, пишите БЕЗ пробелов и запятых (или сверьте инструкцию в шапке бланка).</p></div>"}, {"num": "13", "shortTitle": "Сочинение 13.1 / 13.2 / 13.3", "part": "Часть 2", "title": "Задание № 13: Сочинение-рассуждение (подробный разбор 13.1, 13.2 и 13.3)", "fipiSpec": {"number": "№ 13", "score": "7 баллов", "time": "60 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Выбор темы и структура (минимум 70 слов!)</h4>\n      <p>Из 3 предложенных тем вы выбираете <strong>ОДНУ</strong>. Самой популярной и предсказуемой является <strong>13.3</strong> (объяснение нравственного понятия). Все три сочинения имеют 4 чётких абзаца:</p>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>Вариант 13.3 (понятие: дружба, смелость, милосердие, доброта, выбор...):</strong></div>\n        <div class=\"math-subtext\">• <strong>Абзац 1 (Вступление + определение):</strong> Дайте определение понятию и прокомментируйте его.<br>• <strong>Абзац 2 (Пример №1 из текста):</strong> Приведите конкретный эпизод из прочитанного текста (с номерами предложений) + поясните, как он доказывает тезис.<br>• <strong>Абзац 3 (Пример №2 из жизненного опыта):</strong> Пример из жизни, литературы, истории или кино + микровывод.<br>• <strong>Абзац 4 (Вывод):</strong> Итог рассуждения («Таким образом...»).</div>\n        <div class=\"math-row\"><strong>Вариант 13.2 (объяснение цитаты из текста):</strong> Тезис (как вы понимаете фразу из финала текста) + 2 примера ИЗ ТЕКСТА с номерами предложений + вывод.</div>\n        <div class=\"math-row\"><strong>Вариант 13.1 (лингвистическая цитата):</strong> Тезис + 2 примера языковых явлений из текста (например: метафора в предл. 5, двоеточие в предл. 12) + вывод.</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Начните с 13.3 (если не уверены в 13.1/13.2):</strong> Чётко дайте определение слова (2–3 предложения).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Приведите 2 аргумента:</strong> В 13.3: первый СТРОГО из прочитанного текста, второй из жизненного опыта / прочитанных книг.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Проверьте объём и грамотность:</strong> Слов должно быть от 70 (оптимум 90–140). Если меньше 70 слов — оценка за сочинение 0 баллов! Учитываются общие баллы грамотности ГК1–ГК4 за изложение + сочинение (суммарно минимум 140 слов).</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">Готовые клише для 13.3 (Дружба)</div>\n      <p><strong>Условие:</strong> Напишите вступление и связку для 13.3 на тему «Что такое настоящая дружба?»</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p><strong>Вступление:</strong> «Настоящая дружба — это бескорыстные взаимоотношения между людьми, основанные на доверии, уважении и готовности прийти на помощь. На мой взгляд, верный друг не оставит в беде. Докажем это примерами из текста и жизни».</p><p><strong>Связка к 1 примеру:</strong> «Обратимся к прочитанному тексту. В предложениях 12–15 герой...»</p><div class=\"task-answer-box\">Ответ: <strong>Универсальная структура</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Отсутствие комментария или пересказ</strong><p>В аргументах нельзя просто пересказать сюжет! Обязательно в конце каждого примера пишите 1–2 предложения ПОЯСНЕНИЯ («Этот поступок доказывает, что...»).</p></div>"}];
window.OGE_TASKS_BY_NUMBER.social = [{"num": "1", "shortTitle": "Раскрытие понятий", "part": "Часть 2", "title": "Задание № 1: Выбор двух понятий и раскрытие смысла одного из них", "fipiSpec": {"number": "№ 1", "score": "2 балла", "time": "6–8 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Как получить максимум (2 балла) за задание №1</h4>\n      <p>Задание №1 проверяет базовые термины из 5 сфер общества. Вам даётся список из 5 понятий. Нужно: 1) выписать <strong>два</strong> понятия, относящиеся к указанной теме; 2) <strong>раскрыть смысл любого ОДНОГО</strong> из них.</p>\n      <div class=\"task-formula-box\">\n        <div class=\"math-row\"><strong>Обязательные термины, которые часто встречаются:</strong></div>\n        <div class=\"math-subtext\">• <strong>Деятельность</strong> — присущая человеку форма взаимодействия с окружающим миром, направленная на его познание и преобразование.<br>• <strong>Инфляция</strong> — процесс обесценивания денег, проявляющийся в устойчивом росте общего уровня цен на товары и услуги.<br>• <strong>Мораль</strong> — система норм и правил поведения, основанных на представлениях людей о добре и зле.<br>• <strong>Правонарушение</strong> — общественно опасное (вредное), противоправное, виновное деяние, за которое предусмотрена юридическая ответственность.<br>• <strong>Семья</strong> — малая социальная группа, основанная на браке или кровном родстве, члены которой связаны общим бытом и взаимной ответственностью.</div>\n      </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Выпишите строго два понятия:</strong> Не пишите три понятия — если ошибётесь в третьем, балл снимут.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Дайте полное определение:</strong> Определение должно содержать родовой признак («это форма...», «это группа...») и не менее двух существенных признаков!</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Не определяйте слово через само себя:</strong> Нельзя писать: «Потребность — это то, что человеку нужно потреблять» (это тавтология = 0 баллов).</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Экономика)</div>\n      <p><strong>Условие:</strong> Какие два из перечисленных понятий используются для описания факторов производства? Выпишите их и раскройте смысл одного: труд, издержки, капитал, инфляция, бюджет.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>1) Факторы производства: <strong>труд, капитал</strong>.<br>2) <strong>Труд</strong> — это целесообразная деятельность человека по созданию товаров и услуг, требующая приложения физических и умственных усилий.</p><div class=\"task-answer-box\">Ответ: <strong>2 балла</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Бытовое определение</strong><p>Короткие фразы вроде «Семья — это мама, папа и я» не засчитываются! Пишите признаки научного обществоведческого определения.</p></div>"}, {"num": "2", "shortTitle": "Человек и природа", "part": "Часть 1", "title": "Задание № 2: Человек, личность, деятельность, биосоциальная сущность", "fipiSpec": {"number": "№ 2", "score": "1 балл", "time": "2 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Ключевые отличия человека от животного</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>Биологическое (общее с животными):</strong> инстинкты, рефлексы, строение тела, потребности в пище, сне, воде, самосохранении.</div>\n       <div class=\"math-row\"><strong>Социальное (только у человека):</strong> речь, мышление, творчество, сознание, постановка целей, мораль, труд (изготовление орудий).</div>\n       <div class=\"math-row\"><strong>Индивид</strong> (единичный представитель) → <strong>Индивидуальность</strong> (уникальные черты) → <strong>Личность</strong> (социально значимые качества, ответственность, взгляды).</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Определите сферу:</strong> Ищите, что характеризует человека как члена общества (личность) или как организм (индивид).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Исключите неверные суждения:</strong> В тесте с 4 вариантами правильный всегда один.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Что из перечисленного иллюстрирует социальную природу человека? 1) способность ощущать холод 2) потребность в дыхании 3) забота о престарелых родителях 4) реакция зрачка на свет</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Забота о родителях формируется в обществе (мораль).</p><div class=\"task-answer-box\">Ответ: <strong>3</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Сознание vs Инстинкт</strong><p>Животные действуют по инстинктам и приспосабливаются к природе; человек ставит осознанные цели и преобразует природу под себя.</p></div>"}, {"num": "3", "shortTitle": "Духовная сфера", "part": "Часть 1", "title": "Задание № 3: Образование, наука, религия, искусство, мораль", "fipiSpec": {"number": "№ 3", "score": "1 балл", "time": "2 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Элементы духовной культуры</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>Образование в РФ (уровни):</strong></div>\n       <div class=\"math-subtext\">1) Дошкольное (детсад); 2) Начальное общее (1–4 кл.); 3) Основное общее (5–9 кл., <strong>обязательно!</strong>); 4) Среднее общее (10–11 кл., <strong>обязательно до 18 лет/по Конституции общее образование обязательно!</strong>).</div>\n       <div class=\"math-row\"><strong>Тенденции образования:</strong> гуманизация (внимание к личности ученика), гуманитаризация (роль гуманитарных наук), интернационализация, компьютеризация, непрерывность.</div>\n       <div class=\"math-row\"><strong>Наука vs Религия:</strong> Наука опирается на доказательства и эксперимент; религия — на веру в сверхъестественное; искусство — на художественные образы.</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Сверьте признаки:</strong> Ищите отличительные черты (вера, образность, доказательность, ступени образования).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Запомните уровни:</strong> Основное общее образование — 9 классов, Среднее общее — 10–11 классы.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Ольга учится в 9 классе гимназии. На каком уровне образования она находится?</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>5–9 классы — это основное общее образование.</p><div class=\"task-answer-box\">Ответ: <strong>Основное общее</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ СПО vs ВУЗ</strong><p>Колледж и техникум — это <strong>среднее профессиональное</strong> образование (СПО), а университет/институт — <strong>высшее</strong>!</p></div>"}, {"num": "4", "shortTitle": "Суждения о человеке", "part": "Часть 1", "title": "Задание № 4: Выбор верных суждений (сфера «Человек и культура»)", "fipiSpec": {"number": "№ 4", "score": "1 балл", "time": "2–3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Анализ двух суждений (А и Б)</h4>\n     <p>Формат задания №4: даны два утверждения (А и Б). Варианты ответа: 1) верно только А; 2) верно только Б; 3) верны оба; 4) оба неверны.</p>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>Темы для повторения:</strong> социализация (первичная — семья, вторичная — школа/армия), моральные нормы (выполняются добровольно/совестью, без штрафов государства), глобальные проблемы человечества, патриотизм и гражданственность.</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Проверьте А отдельно:</strong> Не читайте Б, пока не поставите «+» или «−» возле А.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Ищите категоричные слова:</strong> Слова «только», «всегда», «исключительно» часто делают суждение НЕВЕРНЫМ.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> А. Мораль поддерживается силой общественного мнения и совестью человека. Б. Моральные нормы закреплены исключительно в Уголовном кодексе РФ.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>А — верно. Б — ложь (в УК закреплены правовые нормы, а не моральные).</p><div class=\"task-answer-box\">Ответ: <strong>1</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Совпадение морали и права</strong><p>Не путайте: мораль — оценка «добро/зло», право — оценка «законно/незаконно» и государственное принуждение.</p></div>"}, {"num": "5", "shortTitle": "Анализ фотографии", "part": "Часть 2", "title": "Задание № 5: Анализ изображения (форма деятельности / проблема / правило)", "fipiSpec": {"number": "№ 5", "score": "3 балла", "time": "7–9 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Как получить все 3 балла за задание по картинке</h4>\n     <p>К одной фотографии даётся <strong>4 вопроса</strong>. Ответ нужно писать чётко, по пунктам (1, 2, 3, 4).</p>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>Что чаще всего изображено на фото ФИПИ:</strong></div>\n       <div class=\"math-subtext\">• Покупка в магазине / оплата картой (потребление, финансовая грамотность).<br>• Субботник / посадка деревьев / сортировка мусора (экологическое поведение).<br>• Выборы / голосование (политическое участие).<br>• Семья за столом / помощь пожилым / чтение книг (традиции, образование, семья).</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Вопрос 1 (Название явления/вида):</strong> Назовите точно, например: «вид деятельности — труд / учёба / игра» или «рациональное поведение потребителя».</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Вопросы 2–4 (Правила / Объяснения):</strong> Сформулируйте два-три развёрнутых правила или аргумента (полными предложениями, а не одним словом!).</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ (Выборы)</div>\n      <p><strong>Условие:</strong> На фото люди опускают бюллетени в урну для голосования. 1) Какое политическое право иллюстрирует фото? 2) С какого возраста в РФ граждане имеют это право? 3) Зачем участвовать в выборах?</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>1) Избирательное право (право избирать). 2) С 18 лет. 3) Чтобы влиять на состав органов власти, выражать свою гражданскую позицию и контролировать политику государства.</p><div class=\"task-answer-box\">Ответ: <strong>3 балла</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Односложные ответы</strong><p>Если в вопросе просят «объясните, почему...», ответ в 2 слова не засчитают — пишите развёрнутое предложение!</p></div>"}, {"num": "6", "shortTitle": "Финграмотность", "part": "Часть 2", "title": "Задание № 6: Финансовая безопасность и защита от мошенников", "fipiSpec": {"number": "№ 6", "score": "2 балла", "time": "4–5 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Стандартная задача по финансовой грамотности</h4>\n     <p>В задании описана жизненная ситуация с банковской картой, СМС от «службы безопасности», звонком о «выигрыше», «выгодным» кредитом или покупкой в интернете.</p>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>Два вопроса в №6:</strong></div>\n       <div class=\"math-subtext\">1. <strong>В чём состоит опасность</strong> данной ситуации? (Ответ: это финансовое мошенничество / фишинг — злоумышленники получат доступ к счёту и украдут все деньги!).<br>2. <strong>Как правильно поступить</strong> в данной ситуации? (Ответ: немедленно прекратить разговор / не сообщать ПИН-код, CVV и коды из СМС, не переходить по ссылкам и позвонить в банк по официальному номеру с обратной стороны карты!).</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Укажите риск:</strong> Чётко напишите про риск потери личных денег со счёта.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Укажите безопасное действие:</strong> Всегда рекомендуйте: положить трубку, никому не называть CVV/СМС-код, проверить всё через официальное приложение банка.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Анне позвонил «сотрудник банка» и попросил назвать код из СМС, чтобы отменить подозрительный перевод. В чём опасность и как поступить?</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>1) Опасность: это мошенник, который, получив код из СМС, спишет деньги со счёта Анны.<br>2) Как поступить: прервать звонок, никому не сообщать коды и самостоятельно перезвонить в банк по номеру на карте.</p><div class=\"task-answer-box\">Ответ: <strong>2 балла</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Забыт ответ на первый вопрос</strong><p>Всегда проверяйте, что вы ответили на ОБА вопроса задания №6!</p></div>"}, {"num": "7", "shortTitle": "Экономика: основы", "part": "Часть 1", "title": "Задание № 7: Экономические ресурсы, факторы производства, рыночный механизм", "fipiSpec": {"number": "№ 7", "score": "1 балл", "time": "2–3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Факторы производства и доходы от них (обязательно знать!)</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>5 факторов производства → факторный доход:</strong></div>\n       <div class=\"math-subtext\">1. <strong>Труд</strong> → Заработная плата<br>2. <strong>Земля</strong> (все природные ресурсы) → Рента<br>3. <strong>Капитал</strong> (станки, здания, деньги) → Процент<br>4. <strong>Предпринимательские способности</strong> → Прибыль<br>5. <strong>Информация</strong> → Роялти / Прибыль</div>\n       <div class=\"math-row\"><strong>Закон спроса и предложения:</strong> Цена растёт → Спрос падает, Предложение растёт.</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Различайте благо, товар и услугу:</strong> Товар можно потрогать (хлеб), услуга — действие (стрижка, ремонт).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Сопоставьте фактор и доход:</strong> Зарплата — только от труда, рента — от земли!</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Какой фактор производства приносит владельцу доход в виде ренты?</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Земля (природные ресурсы).</p><div class=\"task-answer-box\">Ответ: <strong>Земля</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Экономические системы</strong><p>Традиционная (обычаи), Командная/плановая (государство всё решает), Рыночная (спрос и предложение, частная собственность), Смешанная (рынок + роль государства).</p></div>"}, {"num": "8", "shortTitle": "Экономика: деньги/налоги", "part": "Часть 1", "title": "Задание № 8: Налоги, бюджет, банки, инфляция, безработица", "fipiSpec": {"number": "№ 8", "score": "1 балл", "time": "2–3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Налоги (прямые и косвенные) и бюджет</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>Прямые налоги</strong> (берутся прямо с дохода или имущества): НДФЛ (13%), налог на прибыль, транспортный налог, налог на имущество, земельный налог.</div>\n       <div class=\"math-row\"><strong>Косвенные налоги</strong> (включены в цену товара в магазине): <strong>НДС</strong>, <strong>акцизы</strong> (табак, алкоголь, бензин), таможенные пошлины.</div>\n       <div class=\"math-row\"><strong>Госбюджет:</strong> Профицит (доходы > расходов), Дефицит (расходы > доходов), Сбалансированный (доходы = расходы).</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Определите тип налога:</strong> Спрашивается про налог в цене товара → косвенный (НДС/акциз).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Функции денег:</strong> Мера стоимости, средство обращения, средство платежа, средство накопления, мировые деньги.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Что из перечисленного относится к косвенным налогам? 1) НДФЛ 2) налог на имущество 3) НДС 4) земельный налог</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>НДС включён в цену товаров — это косвенный налог.</p><div class=\"task-answer-box\">Ответ: <strong>3</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ ЦБ РФ vs Коммерческие банки</strong><p>Выдавать кредиты гражданам и принимать вклады могут только <strong>коммерческие банки</strong>! Центральный банк (Банк России) печатает деньги, ставит ключевую ставку и работает только с банками и государством.</p></div>"}, {"num": "9", "shortTitle": "Суждения об экономике", "part": "Часть 1", "title": "Задание № 9: Анализ двух суждений по экономике (А и Б)", "fipiSpec": {"number": "№ 9", "score": "1 балл", "time": "2–3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Частые темы суждений А и Б в №9</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>• Инфляция:</strong> опасна снижением покупательной способности денег; выигрывают от неё те, кто брал кредиты под фиксированный % (отдают обесцененными деньгами), проигрывают вкладчики и пенсионеры.</div>\n       <div class=\"math-row\"><strong>• Конкуренция:</strong> заставляет производителей улучшать качество и снижать издержки. Монополия — диктат одного продавца (с ней борется ФАС).</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Проверяйте термины:</strong> Оценивайте логику каждого утверждения независимо.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Исключайте крайности:</strong> Например: «Рыночная экономика полностью исключает участие государства» — ложь.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> А. Повышение производительности труда способствует снижению издержек. Б. При дефиците бюджета расходы превышают доходы.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Оба верны.</p><div class=\"task-answer-box\">Ответ: <strong>3</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Издержки производства</strong><p>Постоянные издержки НЕ зависят от объёма выпуска (аренда, оклад охраны). Переменные ЗАВИСЯТ от объёма (сырьё, сдельная зарплата, электроэнергия станков).</p></div>"}, {"num": "10", "shortTitle": "Социальная сфера", "part": "Часть 1", "title": "Задание № 10: Социальная структура, мобильность, конфликты, семья", "fipiSpec": {"number": "№ 10", "score": "1 балл", "time": "2 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Социальные группы, стратификация и мобильность</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>4 критерия стратификации (социального неравенства):</strong> Доход, Власть, Образование, Престиж профессии.</div>\n       <div class=\"math-row\"><strong>Социальная мобильность:</strong></div>\n       <div class=\"math-subtext\">• <strong>Горизонтальная:</strong> без изменения статуса (переход в другой город, смена одной работы на аналогичную, развод/брак).<br>• <strong>Вертикальная:</strong> с изменением статуса (повышение — восходящая, увольнение/понижение — нисходящая).</div>\n       <div class=\"math-row\"><strong>Типы семей:</strong> Нуклеарная (родители + дети) vs Расширенная/многопоколенная (+ бабушки/дедушки).</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Определите, изменился ли статус человека:</strong> Вырос в должности/доходе → вертикальная восходящая; просто перешёл в другую школу → горизонтальная.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Социальные санкции:</strong> Бывают формальные (премия, штраф, тюрьма) и неформальные (похвала, бойкот, насмешка).</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Гражданин К. сменил место работы, заняв точно такую же должность инженера в другой компании с той же зарплатой. Какой это вид мобильности?</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Статус не изменился — горизонтальная мобильность.</p><div class=\"task-answer-box\">Ответ: <strong>Горизонтальная</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Социальный лифт</strong><p>Главные каналы социальной мобильности («лифты»): образование, армия, брак, церковь, бизнес, политика.</p></div>"}, {"num": "11", "shortTitle": "Суждения о социуме", "part": "Часть 1", "title": "Задание № 11: Выбор верных суждений о социальной сфере (А и Б)", "fipiSpec": {"number": "№ 11", "score": "1 балл", "time": "2 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Социальные нормы, роли и конфликты</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>Социальный статус:</strong> предписанный (пол, национальность, возраст, дворянство) vs достигаемый (врач, студент, чемпион, муж).</div>\n       <div class=\"math-row\"><strong>Отклоняющееся (девиантное) поведение:</strong> может быть как негативным (преступность, алкоголизм), так и позитивным (героизм, гениальность, самопожертвование)!</div>\n       <div class=\"math-row\"><strong>Пути выхода из конфликта:</strong> компромисс (взаимные уступки), сотрудничество, избегание, приспособление, арбитраж.</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Проверьте оба суждения:</strong> Вспоминайте, что девиантное поведение — не только плохое, но и любое отклонение от обычной нормы (даже гениальность).</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> А. Возраст относится к достигаемому статусу человека. Б. Девиантное поведение всегда является преступлением.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Оба неверны (возраст — предписанный статус; преступление — это делинквентное поведение, лишь часть девиантного).</p><div class=\"task-answer-box\">Ответ: <strong>4</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Этносы (народы)</strong><p>Племя → Народность → Нация. Главный признак нации — единая культура, язык, территория и экономические связи.</p></div>"}, {"num": "12", "shortTitle": "График / Диаграмма", "part": "Часть 2", "title": "Задание № 12: Анализ социологического опроса (сходство и различие)", "fipiSpec": {"number": "№ 12", "score": "4 балла", "time": "8–12 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Шаблон идеального ответа на 4 балла!</h4>\n     <p>Самое «дорогое» задание в ОГЭ по обществознанию! По графику или таблице нужно написать 4 элемента:</p>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>1. Сходство (что общего у двух групп):</strong> Например, «Одинаковая доля (по 25%) опрошенных в обеих группах выбрала вариант Х...» ИЛИ «Большинство в обеих группах отметили вариант Y».</div>\n       <div class=\"math-row\"><strong>2. Предположение о сходстве:</strong> «Возможно, это связано с тем, что...» (объясняем разумной причиной!).</div>\n       <div class=\"math-row\"><strong>3. Различие (чем они отличаются):</strong> «Среди 25-летних вариант Z выбрали 40%, а среди 55-летних — только 10% (намного больше молодёжи)».</div>\n       <div class=\"math-row\"><strong>4. Предположение о различии:</strong> «Вероятно, молодые люди чаще сталкиваются с...»</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Сначала запишите факты строго по цифрам:</strong> Обязательно называйте конкретные группы (например, «жители города Z» и «юноши и девушки») и называйте варианты ответа с диаграммы.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>К каждому факту допишите объяснение:</strong> Начинайте объяснение со слов «Вероятно, это обусловлено тем, что...» — 2–3 логичных предложения.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> График: Опрос «Зачем нужно заниматься спортом?» среди 20-летних и 50-летних.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>1) <strong>Сходство:</strong> В обеих группах самым популярным ответом стал «Для здоровья» (60% и 65%). <em>Предположение:</em> забота о здоровье важна для человека в любом возрасте.<br>2) <strong>Различие:</strong> Вариант «Для красоты фигуры» выбрали 35% молодых и лишь 5% 50-летних. <em>Предположение:</em> молодёжь больше озабочена внешним видом и поиском пары.</p><div class=\"task-answer-box\">Ответ: <strong>4 балла</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Забытая привязка к группам</strong><p>Если написать просто «большинство выбрало вариант А» без уточнения <em>«в обеих группах»</em>, балл не засчитают!</p></div>"}, {"num": "13", "shortTitle": "Политика и власть", "part": "Часть 1", "title": "Задание № 13: Государство, формы правления и политические режимы", "fipiSpec": {"number": "№ 13", "score": "1 балл", "time": "2–3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Три кита формы государства</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>1. Форма правления (кто у власти?):</strong> Монархия (наследуется: абсолютная / конституционная) vs Республика (выбирается: президентская / парламентская / смешанная).</div>\n       <div class=\"math-row\"><strong>2. Территориально-государственное устройство:</strong> Унитарное (нет субъектов со своими законами, например Франция, Япония) vs Федерация (субъекты со своими парламентами, как Россия, США).</div>\n       <div class=\"math-row\"><strong>3. Политический режим (КАК правят?):</strong></div>\n       <div class=\"math-subtext\">• <strong>Демократия:</strong> выборы, плюрализм, разделение властей, права человека, оппозиция.<br>• <strong>Авторитаризм:</strong> власть в одних руках, оппозиция подавлена, но экономика и личная жизнь относительно свободны.<br>• <strong>Тоталитаризм:</strong> тотальный контроль над ВСЕМ (мысли, быт, одна идеология, террор).</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Внимательно читайте вопрос:</strong> Не путайте форму правления (республика/монархия) с политическим режимом (демократия/тоталитаризм)!</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Признаки любого государства:</strong> Суверенитет, единая территория, налоги, монополия на законы и принуждение.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> В стране Z проходят альтернативные выборы, действует свободная пресса и легальная оппозиция. Какой политический режим в стране Z?</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Это признаки демократического режима.</p><div class=\"task-answer-box\">Ответ: <strong>Демократический</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Абсолютная vs Парламентская монархия</strong><p>В Великобритании монархия парламентская (король царствует, но не правит — власть у парламента), а в Саудовской Аравии — абсолютная.</p></div>"}, {"num": "14", "shortTitle": "Выборы и партии", "part": "Часть 1", "title": "Задание № 14: Суждения о выборах, референдуме, партиях и СМИ (А и Б)", "fipiSpec": {"number": "№ 14", "score": "1 балл", "time": "2–3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Выборы, референдум и партии</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>Выборы vs Референдум:</strong> На выборах избирают людей/партии; на референдуме голосуют «ЗА» или «ПРОТИВ» конкретного закона, вопроса или Конституции.</div>\n       <div class=\"math-row\"><strong>Типы партий:</strong> Правящая vs Оппозиционная; Массовые (много членов, работают постоянно) vs Кадровые (собираются только перед выборами); Консервативные, Либеральные, Социал-демократические.</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Проверьте полномочия СМИ:</strong> СМИ называют «четвёртой властью» (но юридически к ветвям власти относятся только законодательная, исполнительная, судебная!).</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> А. Референдум — это всенародное голосование по важнейшим государственным вопросам. Б. Президентом РФ может быть избран гражданин с 18 лет.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>А — верно. Б — ложь (Президентом РФ можно стать с 35 лет, проживая в РФ не менее 25 лет).</p><div class=\"task-answer-box\">Ответ: <strong>1</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Возрастной ценз в РФ</strong><p>Голосовать — с 18 лет; стать депутатом Госдумы — с 21 года; стать Президентом — с 35 лет!</p></div>"}, {"num": "15", "shortTitle": "Сопоставление (таблица)", "part": "Часть 1", "title": "Задание № 15: Установление соответствия (полномочия, права/обязанности, виды)", "fipiSpec": {"number": "№ 15", "score": "2 балла", "time": "3–4 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Как не потерять баллы в задании №15 (цена 2 балла!)</h4>\n     <p>Чаще всего в №15 сопоставляют: <strong>ветви власти</strong> (Госдума, Правительство, Президент, Суды), <strong>права и обязанности</strong>, <strong>налоги</strong>, <strong>экологические/гражданские права</strong> или <strong>виды юридической ответственности</strong>.</p>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>Разделение властей в РФ:</strong></div>\n       <div class=\"math-subtext\">• <strong>Законодательная (Федеральное Собрание: Совет Федерации + Госдума):</strong> принимает законы, утверждает бюджет (Госдума), объявляет амнистию.<br>• <strong>Исполнительная (Правительство РФ):</strong> разрабатывает и исполняет бюджет, управляет федеральной собственностью.<br>• <strong>Судебная (Конституционный, Верховный суды):</strong> осуществляет правосудие.<br>• <strong>Президент РФ (Глава государства):</strong> подписывает законы, Верховный Главнокомандующий, помилование (одного человека!), внешняя политика.</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Разбирайте каждый пункт А, Б, В, Г, Д по очереди:</strong> В ответе всегда ровно 5 цифр (например: <code>12132</code>).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Запомните: Амнистия — Госдума, Помилование — Президент!:</strong> Правительство РАЗРАБАТЫВАЕТ и ИСПОЛНЯЕТ бюджет, а Госдума его ПРИНИМАЕТ/УТВЕРЖДАЕТ.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Сопоставьте: А) управление федеральной собственностью Б) принятие федеральных законов В) осуществление помилования. (1-Президент, 2-Госдума, 3-Правительство)</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>А — 3, Б — 2, В — 1.</p><div class=\"task-answer-box\">Ответ: <strong>321...</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Один лишний символ</strong><p>За 1 ошибку в последовательности ставится 1 балл, за 2 ошибки — 0 баллов.</p></div>"}, {"num": "16", "shortTitle": "Право и Конституция", "part": "Часть 1", "title": "Задание № 16: Основы конституционного строя и права граждан РФ", "fipiSpec": {"number": "№ 16", "score": "1 балл", "time": "2–3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Глава 1 и 2 Конституции РФ</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>Основы конституционного строя РФ (ст. 1–16):</strong></div>\n       <div class=\"math-subtext\">• Демократическое, федеративное, правовое, социальное, светское государство с республиканской формой правления.<br>• Носитель суверенитета и единственный источник власти — многонациональный народ.<br>• Высшая ценность — человек, его права и свободы.</div>\n       <div class=\"math-row\"><strong>Обязанности гражданина РФ (их всего 7, выучите!):</strong></div>\n       <div class=\"math-subtext\">1) Соблюдать Конституцию и законы; 2) Платить налоги; 3) Беречь природу; 4) Заботиться о сохранении памятников культуры; 5) Защищать Отечество; 6) Родители обязаны заботиться о детях (а совершеннолетние трудоспособные дети — о нетрудоспособных родителях); 7) Получить основное общее образование (9 классов).</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Права vs Обязанности:</strong> Право можно не использовать (право на труд, на отдых), а обязанность строго обязательна (налоги, охрана природы, армия)!</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Светское государство:</strong> Никакая религия не может устанавливаться в качестве государственной или обязательной.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Что из перечисленного является конституционной ОБЯЗАННОСТЬЮ гражданина РФ? 1) участие в выборах 2) уплата налогов 3) выбор профессии 4) обращение в суд</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Выборы и выбор профессии — права. Уплата налогов — обязанность!</p><div class=\"task-answer-box\">Ответ: <strong>2</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Участие в выборах</strong><p>Голосование на выборах в России — это <strong>ПРАВО</strong>, а НЕ обязанность!</p></div>"}, {"num": "17", "shortTitle": "Отрасли права", "part": "Часть 1", "title": "Задание № 17: Гражданское, семейное, трудовое, административное и уголовное право", "fipiSpec": {"number": "№ 17", "score": "1 балл", "time": "2–3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Возрастные пороги и отрасли права</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>1. Уголовное право:</strong> преступления (кража, убийство, грабёж, угон). Ответственность с <strong>16 лет</strong> (за тяжкие, вроде кражи, грабежа, убийства — с <strong>14 лет</strong>!).</div>\n       <div class=\"math-row\"><strong>2. Административное право:</strong> проступки (безбилетный проезд, переход на красный, мелкое хулиганство). Ответственность с <strong>16 лет</strong> (штраф, предупреждение).</div>\n       <div class=\"math-row\"><strong>3. Трудовое право:</strong> заключение трудового договора по общему правилу с <strong>16 лет</strong> (с 15 — лёгкий труд, с 14 — с согласия родителя!). Рабочая неделя до 16 лет — не более 24 ч, с 16 до 18 — не более 35 ч!</div>\n       <div class=\"math-row\"><strong>4. Гражданское право:</strong> имущество, сделки, купля-продажа, наследование, защита чести. Частичная дееспособность с <strong>14 лет</strong>, полная — с <strong>18 лет</strong> (или эмансипация с 16!).</div>\n       <div class=\"math-row\"><strong>5. Семейное право:</strong> брачный возраст 18 лет (при уважит. причинах с 16). Развод в ЗАГСе (по обоюдному согласию без общих несовершеннолетних детей), иначе — через СУД.</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Определите вид ситуации:</strong> Конфликт с работодателем — трудовое; покупка телефона — гражданское; переход дороги на красный — административное.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> 15-летний подросток перешёл дорогу на красный свет. К какому виду ответственности он может быть привлечён?</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Административная ответственность наступает с 16 лет, поэтому к административной ответственности привлечь нельзя (но родителей могут наказать за ненадлежащее воспитание).</p><div class=\"task-answer-box\">Ответ: <strong>Ответственности не подлежит / с 16 лет</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Увольнение/Ночная смена несовершеннолетних</strong><p>Работникам до 18 лет ЗАПРЕЩЕНЫ: испытательный срок, работа ночью (с 22 до 6), сверхурочная работа и командировки!</p></div>"}, {"num": "18", "shortTitle": "Суждения о праве", "part": "Часть 1", "title": "Задание № 18: Анализ двух суждений по праву (А и Б)", "fipiSpec": {"number": "№ 18", "score": "1 балл", "time": "2–3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Тонкости права для А и Б</h4>\n     <div class=\"task-formula-box\">\n       <div class=\"math-row\"><strong>• Презумпция невиновности:</strong> обвиняемый считается невиновным, пока его виновность не доказана приговором суда, вступившим в силу. Он НЕ обязан доказывать свою невиновность!</div>\n       <div class=\"math-row\"><strong>• Правоспособность vs Дееспособность:</strong> Правоспособность (иметь права) возникает с <strong>рождения</strong>! Дееспособность (осуществлять права своими действиями) — в полном объёме с <strong>18 лет</strong>.</div>\n     </div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Проверяйте определения:</strong> Не путайте административный штраф (КоАП) с уголовным штрафом (УК).</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> А. Правоспособность гражданина возникает с момента его рождения. Б. Правоспособность прекращается с наступлением совершеннолетия.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>А — верно, Б — ложь (прекращается только со смертью).</p><div class=\"task-answer-box\">Ответ: <strong>1</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Завещание и брачный договор</strong><p>Брачный договор регулирует ТОЛЬКО имущественные отношения супругов (он НЕ может регулировать, кто моет посуду или с кем живут дети после развода!).</p></div>"}, {"num": "19", "shortTitle": "Сходство и различие", "part": "Часть 1", "title": "Задание № 19: Сравнение двух социальных/правовых явлений", "fipiSpec": {"number": "№ 19", "score": "2 балла", "time": "3 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Как правильно распределять черты сходства и различия</h4>\n     <p>Даны два явления (например: «налог и штраф», «административный проступок и преступление», «традиционная и рыночная экономика»). Нужно распределить 4 признака: первые 2 цифры — черты <strong>сходства</strong>, следующие 2 — черты <strong>различия</strong>.</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Читайте вопрос для каждого из 4 признаков:</strong> 1) Справедливо ли это для ПЕРВОГО? 2) Справедливо ли для ВТОРОГО?</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Формат ответа:</strong> Если для обоих «Да» — это сходство (ставим в начало). Если для одного «Да», для другого «Нет» — это различие (в конец).</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Сравните административное и уголовное право: 1) отрасль публичного права 2) регулируется УК РФ 3) устанавливает наказания за правонарушения 4) влечёт судимость.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Сходство (для обоих): 1, 3. Различие (только для уголовного): 2, 4.</p><div class=\"task-answer-box\">Ответ: <strong>1324</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Порядок цифр</strong><p>Первые 2 цифры — обязательно черты СХОДСТВА, последние 2 — РАЗЛИЧИЯ (1324, а не 2413!).</p></div>"}, {"num": "20", "shortTitle": "Таблица с пропуском", "part": "Часть 1", "title": "Задание № 20: Заполнение пропуска в классификационной таблице", "fipiSpec": {"number": "№ 20", "score": "1 балл", "time": "2 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Что обычно зашифровано в пропуске №20</h4>\n     <p>Даётся таблица из 2 строк: одна заполнена полностью (образец), во второй вместо термина или характеристики стоит знак вопроса <strong>«?»</strong>. Примеры тем: ветви власти, уровни научного познания (эмпирический/теоретический), виды потребностей, факторы производства.</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Поймите логику первой строки:</strong> Определите пару: «Термин — Пояснение» или «Понятие — Пример».</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Впишите одно слово (или словосочетание) в бланк:</strong> Соблюдайте именительный падеж.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Таблица: Методы научного познания. Наблюдение — эмпирический; Выдвижение гипотезы — ?</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Гипотеза, теория, моделирование относятся к теоретическому уровню.</p><div class=\"task-answer-box\">Ответ: <strong>теоретический</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Формат слова</strong><p>Пишите слово строго в том роде и падеже, в котором написано слово в левой/правой ячейке выше!</p></div>"}, {"num": "21", "shortTitle": "План текста", "part": "Часть 2", "title": "Задание № 21: Составление плана прочитанного текста", "fipiSpec": {"number": "№ 21", "score": "2 балла", "time": "6–8 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Идеальный план к тексту за 5 минут</h4>\n      <p>Нужно прочитать приведённый текст (обычно 3–5 абзацев) и составить его план.</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Разделите текст по смыслу:</strong> Чаще всего 1 абзац = 1 пункт плана (кроме совсем коротких вводных абзацев).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Назовите каждый пункт:</strong> Называйте пункты назывными предложениями (существительными), например: <em>1. Понятие социализации; 2. Роль семьи в воспитании ребёнка; 3. Влияние школьного коллектива</em>.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 3</div><div class=\"task-step-desc\"><strong>Проверьте логику:</strong> Убедитесь, что ни один важный смысловой фрагмент не пропущен.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Составьте план текста об инфляции (4 абзаца).</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>1. Сущность инфляции и её причины.<br>2. Виды инфляции по темпам роста цен.<br>3. Негативные социально-экономические последствия инфляции.<br>4. Антиинфляционная политика государства.</p><div class=\"task-answer-box\">Ответ: <strong>2 балла</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Цитаты вместо названий</strong><p>Не выписывайте целые предложения из текста в качестве пунктов плана — формулируйте короткие заголовки!</p></div>"}, {"num": "22", "shortTitle": "Поиск по тексту", "part": "Часть 2", "title": "Задание № 22: Поиск ответов на прямые вопросы по тексту", "fipiSpec": {"number": "№ 22", "score": "2 балла", "time": "4–5 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Самые лёгкие 2 балла во второй части</h4>\n      <p>Все ответы на №22 содержатся <strong>непосредственно в самом тексте</strong>. Ничего придумывать не нужно!</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Разбейте вопрос на части:</strong> Обычно в №22 задано 2–3 вопроса (например: 1) Что автор называет ...? 2) Какие два признака ... он выделяет?).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Выпишите точно из текста:</strong> Перепишите нужные предложения или фрагменты без искажения смысла.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Какие три формы политического участия упоминает автор в тексте?</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>Находим абзац про политическое участие и выписываем строго те 3 формы, которые там перечислены.</p><div class=\"task-answer-box\">Ответ: <strong>2 балла</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Лишний ответ</strong><p>Выписывайте только то, что прямо отвечает на вопрос, не нужно переписывать весь абзац целиком.</p></div>"}, {"num": "23", "shortTitle": "Примеры к тексту", "part": "Часть 2", "title": "Задание № 23: Конкретизация положений текста примерами", "fipiSpec": {"number": "№ 23", "score": "3 балла", "time": "8–10 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Как правильно приводить примеры в ОГЭ</h4>\n      <p><strong>Пример — это НЕ общее рассуждение!</strong> Пример должен описывать конкретную жизненную ситуацию с действующими лицами (Иван, государство Z, фирма «Альфа») и конкретными действиями.</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Перечитайте, ЧТО нужно проиллюстрировать:</strong> Если просят 2 примера на 2 разных вида — подпишите, какой пример к какому виду относится.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Моделируйте сценку:</strong> Пишите: «Например, гражданин Петров открыл свою пекарню, нанял работников и стал получать прибыль — это пример...»</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Проиллюстрируйте двумя примерами влияние природы на хозяйственную деятельность человека.</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>1) В странах с жарким тропическим климатом (например, Бразилии) развито выращивание кофе и какао.<br>2) В горных районах (например, Швейцарии) люди развивают горнолыжный туризм и пастбищное животноводство.</p><div class=\"task-answer-box\">Ответ: <strong>3 балла</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Теория вместо примера</strong><p>Фраза «Люди покупают товары, когда снижаются цены» — это НЕ пример, это теория! Пишите: «Когда в магазине у дома снизили цену на яблоки, семья Ивановых купила 5 кг вместо 2 кг».</p></div>"}, {"num": "24", "shortTitle": "Аргументация мнения", "part": "Часть 2", "title": "Задание № 24: Объяснение / аргументация авторской позиции", "fipiSpec": {"number": "№ 24", "score": "2 балла", "time": "6–8 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк заданий ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Отличие №24 от №23</h4>\n      <p>В №23 нужны были <strong>конкретные примеры</strong> (случаи из жизни/истории). В №24 нужны <strong>логические объяснения и аргументы</strong> (причинно-следственные связи, теоретические доводы: «почему это важно?», «к чему это приводит?»).</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Используйте связки «Потому что...», «Это позволяет...»:</strong> Напишите минимум 2 развёрнутых объяснения (по одному на каждый требуемый аргумент).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Не повторяйте слова автора:</strong> Раскройте мысль своими словами с использованием обществоведческих терминов.</div></div></div>", "examples": "<div class=\"task-example-card\">\n      <div class=\"task-example-badge\">ФИПИ</div>\n      <p><strong>Условие:</strong> Объясните, почему правовое государство невозможно без независимого суда (приведите 2 аргумента).</p>\n      <div class=\"task-example-solution\"><strong>Решение:</strong><p>1) Только независимый суд способен объективно рассмотреть спор между гражданином и государственным органом, не боясь давления чиновников.<br>2) Независимый суд гарантирует принцип равенства всех перед законом, даже высших должностных лиц.</p><div class=\"task-answer-box\">Ответ: <strong>2 балла</strong></div></div>\n    </div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Пример вместо аргумента</strong><p>В №24 не рассказывайте истории про Ивана — формулируйте общие закономерности и причины!</p></div>"}];
